INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (7, 'en', 3, 'ref-desc', 'Description', 'Else must follow an If script step or Else If script step. Else cannot follow another Else script step.

When all If script steps and Else If script steps evaluate to false, script execution moves to the Else script step. The script steps under Else are executed, and script execution moves to the End If script step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (7, 'en', 4, 'ref-example1', 'Example 1', 'Performs a find. If no records are found, displays a custom dialog box. If records are found, sorts the found set.

Copy

Perform Find [Restore]
If [Get ( FoundCount ) = 0]
    Show Custom Dialog ["Find Records"; "No records were found."]
Else
    Sort Records [Restore; With dialog: Off]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (7, 'en', 5, 'related', 'Related topics', '- Else If script step

- If structure examples

- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (8, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (8, 'en', 1, 'ref-options', 'Options', 'Specify the Boolean calculation you want evaluated.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (8, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (8, 'en', 3, 'ref-desc', 'Description', 'Else If must follow an If or another Else If script step. Else If cannot follow an Else script step.

When an If script step evaluates to false, script execution moves to the Else If script step. When an Else If statement evaluates to true, the block of steps under the Else If is executed. An evaluation of true ends the Else If process, and upon reaching the next Else If or Else statement, execution will skip to the End If script step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (8, 'en', 4, 'ref-example1', 'Example 1', 'Performs a find and sorts records. If no records match the find request, displays a custom dialog box.

Copy

Perform Find [Restore]
If [ Get ( LastError ) = 0 ]
    Sort Records [Restore; With dialog: Off]
Else If [ Get ( LastError ) = 401 ]
    Show Custom Dialog ["No records were found."]
End If');
