INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (9, 'en', 3, 'ref-desc', 'Description', 'Every If script step must have a corresponding End If script step somewhere after it at the same indentation. Whenever you use an If script step, the script editing pane automatically enters an End If step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (9, 'en', 4, 'ref-example1', 'Example 1', 'Performs a find. If no records are found, displays all records and sorts.

Copy

Perform Find [Restore]
If [Get (FoundCount) = 0]
    Show All Records
    Sort Records [Restore; With dialog: Off]
End If');
