INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (10, 'en', 3, 'ref-desc', 'Description', 'Whenever you use a Loop script step, the script editing pane automatically enters an End Loop step. The steps between Loop and End Loop are automatically indented and the End Loop step is placed at the same indentation level as its corresponding Loop step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (10, 'en', 4, 'ref-example1', 'Example 1', 'Copies the data from Customers::Work Phone to Customers::Day Contact in all records.

Copy

Go to Record/Request/Page [First]
Loop [ Flush: Always ]
    Set Field [Customers::Day Contact; Customers::Work Phone]
    Go to Record/Request/Page [Next; Exit after last: On]
End Loop');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (10, 'en', 5, 'related', 'Related topics', '- Loop script step

