INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (11, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (11, 'en', 1, 'ref-options', 'Options', 'Specifies the Boolean calculation you want evaluated.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (11, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (11, 'en', 3, 'ref-desc', 'Description', 'If the calculation is true (not zero), the script continues with the script step that follows the End Loop script step.

If the calculation is false (zero), the loop is not exited and the script continues with the script step that follows the Exit Loop If script step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (11, 'en', 4, 'ref-example1', 'Example 1', 'Loops through records to export files that are in container fields. Exits the loop if a record has an empty Container field.

Copy

Set Variable [$PATH; Value: Get ( DocumentsPath ) & Products::Container]
Go to Record/Request/Page [First]
Loop [ Flush: Always ]
    Exit Loop If [IsEmpty ( Products::Container )]
    Export Field Contents [Products::Container; "$PATH" ; Create folders: Off]
    Go to Record/Request/Page [Next; Exit after last: On]
End Loop');
