INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (12, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (12, 'en', 1, 'ref-options', 'Options', 'Text Result specifies a text value to pass back to the parent script. The value is typically based on the state of the current script.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (12, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (12, 'en', 3, 'ref-desc', 'Description', 'If Exit Script is used in a sub-script, returns to the main script with or without an optional script result. If the optional script result is specified, the script result is returned and stored in the main script until another sub-script that returns a value is called. The script result gets deleted when you exit the main script. The script result can be stored in a local or global variable for later use.

In scripts run by certain script triggers, you can use this script step to return True or False to determine whether the triggering event is processed. See Script triggers reference.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (12, 'en', 4, 'ref-example1', 'Example 1', 'Performs a find and prints. If no records are found, displays all records and exits the script.

Copy

Perform Find [Restore]
If [Get ( FoundCount ) = 0]
    Show All Records
    Exit Script [Text Result: ]
End If
Print [With dialog: Off]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (12, 'en', 5, 'ref-examplen', 'Example 2', 'Prints unpaid invoices. In the Print sub-script, users can choose whether they want to print invoices. If users choose to print, then Exit Script uses a script result to enter "Printed on <current date>" in the Status field.

Main script: Print Unpaid Invoices

Copy

New Window [Style: Document; Name: "Invoice List"; Using layout: "Print Invoices" (Invoices)]
Perform Find [Restore]
#Calls the "Print" sub-script defined below
Perform Script [Specified: From list; "Print" ; Parameter: ]
#Continues after the sub-script is completed
If [Get ( ScriptResult ) = 1]
    Replace Field Contents [With dialog: Off; Invoices::Status; "Printed on " & Get ( CurrentDate )]
Else
    Show All Records
    Sort Records [Restore; With dialog: Off]
End If

Sub-script: Print

Copy

Show Custom Dialog ["Print Unpaid Invoices"; "Do you want to print unpaid invoices?"]
If [Get ( LastMessageChoice ) = 1]
    Print [With dialog: Off]
Else
    Close Window [Current Window]
End If
#Uses the Result parameter to pass the user''s choice to the main script
Exit Script [Text Result: Get ( LastMessageChoice )]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (12, 'en', 6, 'related', 'Related topics', '- Get(ScriptResult) function

