INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (22, 'en', 0, 'ref-see-also', 'See also', '-
Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (22, 'en', 1, 'ref-options', 'Options', '-
Condition reverts a transaction only if evaluated as true.

-
Error Code returns a custom error code for Get(LastError), Get(LastErrorDetail), and Get(LastErrorLocation) if the provided code is in the range of 5000 through 5499.

-
Error Message returns a custom error message for Get(LastErrorDetail) and Get(LastErrorLocation) if an error code is provided and the provided code is in the range of 5000 through 5499.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (22, 'en', 2, 'ref-orig', 'Originated in version', '19.6.1');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (22, 'en', 3, 'ref-desc', 'Description', 'Revert Transaction:

-
Exits the active record

-
Will activate appropriate triggers

-
Is only allowed between Open Transaction and Commit Transaction, unless it''s used in a nested transaction (see Open Transaction). Otherwise, it returns error 3 ("Command is unavailable").

Revert Transaction will:

-
Jump to the matching Commit Transaction step

Revert Transaction will not:

-
Revert Auto Enter Serial Number Increment

-
Revert Truncate Table

-
Activate the OnRecordRevert script trigger');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (22, 'en', 4, 'ref-example1', 'Example 1', 'Reverts the records in a transaction.

Copy

Open Transaction []
    Set Field [ Assets::Description ; "descriptive text" ]
    Revert Transaction []
Commit Transaction');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (22, 'en', 5, 'ref-examplen', 'Example 2', 'Reverts the records in a transaction if the condition is met.

Copy

Open Transaction []
    Set Field [ Assets::Description ; "description text" ]
    Revert Transaction [ Condition: 1 ]
Commit Transaction');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (22, 'en', 6, 'ref-examplen', 'Example 3', 'Reverts the records in a transaction and returns a custom error.

Copy

Open Transaction []
    Set Field [ Assets::Description ; "descriptive text" ]
    Revert Transaction [ Error Code: 5001 ; Error Message: "custom error text" ]
Commit Transaction');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (22, 'en', 7, 'related', 'Related topics', '-
