INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (39, 'en', 0, 'ref-see-also', 'See also', '- Setting the tab order for data entry

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (39, 'en', 1, 'ref-options', 'Options', 'None.');
