INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (39, 'en', 3, 'ref-desc', 'Description', 'If no field is selected when this script step is performed, this script step moves to the last field of the tab order of the current layout. If a field is formatted as a button, the field object is selected, not the button object.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (39, 'en', 4, 'notes', 'Notes', '- In FileMaker WebDirect, the cursor moves to the selected field.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (39, 'en', 5, 'ref-example1', 'Example 1', 'Controls field entry validation. Can be started with the OnObjectExit script trigger.

Copy

If [IsEmpty ( Customers::First Name )]
    Show Custom Dialog ["You must enter a first name."]
    Go to Previous Field
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (39, 'en', 6, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (40, 'en', 0, 'ref-see-also', 'See also', '- Selecting the current record

- Making a find request

- Previewing and printing information

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (40, 'en', 1, 'ref-options', 'Options', '- First moves to the first record in the file or found set (Browse mode), displays the first find request (Find mode), or moves to the first page in a report (Preview mode).

- Last moves to the last record in the file or found set, displays the last find request, or moves to the last page in a report.

- Previous moves to the previous record in the file or found set, displays the previous find request, or moves to the previous page in a report.

- Next moves to the next record in the file or found set, displays the next find request, or moves to the next page in a report.

- Exit after last exits the script when it reaches the last record in the found set if Next or Previous is selected. You can use Exit after last within a loop to exit the loop after the last record.

- By Calculation specifies a calculation to determine the desired record number, find request number, or page number. Set With dialog to On to display the number in a dialog box for confirmation.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (40, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (40, 'en', 3, 'ref-desc', 'Description', 'In Browse mode, this script step moves to a record; in Find mode it displays a find request, and in Preview mode it moves to a report page.

Server-side scripts and Customer Web Publishing do not support the By Calculation option.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (40, 'en', 4, 'ref-example1', 'Example 1', 'Performs a find, sorts the records, and goes to the first record.

Copy

Perform Find [Restore]
Sort Records [Restore; With dialog: Off]
Go to Record/Request/Page [First]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (40, 'en', 5, 'ref-examplen', 'Example 2', 'Goes to the record number the user enters in the custom dialog box.

Copy

Show Custom Dialog ["Enter the record number you want to view."; Invoices::Record Number]
Go to Record/Request/Page [With dialog: Off ; Invoices::Record Number]
Show All Records');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (40, 'en', 6, 'ref-examplen', 'Example 3', 'Loops through records to export files that are in the Container field. Exits the loop if a record has an empty container field.

Copy

Set Variable [$PATH; Value: Get ( DocumentsPath ) & Products::Container]
Go to Record/Request/Page [First]
Loop [ Flush: Always ]
    Exit Loop If [IsEmpty ( Products::Container )]
    Export Field Contents [Products::Container; "$PATH" ; Create folders: Off]
    Go to Record/Request/Page [Next ; Exit after last: On]
End Loop');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (40, 'en', 7, 'related', 'Related topics', '- Script steps reference

- About formulas');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (41, 'en', 0, 'ref-see-also', 'See also', '- Working with related tables

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (41, 'en', 1, 'ref-options', 'Options', '-
Get related record from specifies the source relationship from a list of tables in the current database. If the table is not in the list or if you need to add or change a relationship, Manage Database displays the Manage Database dialog box, where you can create or edit relationships.

-
Show record using layout specifies the layout in the current file that will be used to display the related record(s).

-
Use external table''s layouts opens the file containing the external table you specify and lets you choose a layout from that file in which to display the related record(s). This option is only available if the source relationship you selected references a table in another file.

-
Show in new window shows the related records in a new window and lets you specify the settings for the new window. See New Window script step.

Tip To bring the new window to the front automatically, add the Select Window script step.

-
Show only related records creates a new found set in the related table with the options either to match the current record or to match the entire found set. The first record in the found set becomes the current record. (If you don''t select this option, Go to Related Record makes the first record in the table''s unsorted order the current record.)

-
Match current record only creates a new found set in the related table containing a set of records that match the current record. For example, if there are three records in the related invoice table that match the customer record in the customer table you are currently viewing, and you want to see all three invoices, use Match current record only to display the three invoices.

-
Match all records in the current found set creates a new found set in the related table that matches all records in the current found set. For example, if you have a found set of ten customers and there are forty invoices in the invoice table that match any of these ten customers, use Match all records in the current found set to display the forty matching invoices. If you don''t define a sort order, the found set will be unsorted.

-
Animation specifies the animation to use when displaying the records (FileMaker Go only).');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (41, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (41, 'en', 3, 'ref-desc', 'Description', 'Suppose you have an Invoices table that''s related to a Customers table and you''re currently looking at a particular invoice. In the Invoices table, you have a button that''s set to Go to Related Record [Customers]. Clicking this button determines which customer record your current invoice is related to and immediately goes to that record in the Customers table. If the record in question is not currently in the Customers table''s found set, the script can perform a find to make the record current.

This script step also works with portal rows. If this script step is used from an active portal row, and the portal''s table is the related table, then the related record in that table is made current. If the portal''s table is not the related table, the first related record in the found set is made current.

When used with a table in an external file, this script step will open the file containing the external table and, if selected, go to the external layout you specify.

There are situations in which a script containing the Go to Related Record script step could modify an unintended set of records. For example:

-
If the related records cannot be found, this script step remains on the current layout.

-
If you select a table occurrence to which there''s no relationship, or a layout that doesn''t refer to the correct table occurrence, FileMaker Pro displays an error message. After the error message displays, script execution continues with the next script step.

-
If there are no related records or no record in the active portal row, the script might produce unexpected results. Use the IsEmpty function to determine if there are no related records before using Go to Related Record.

-
If you have Allow creation of records in this table via this relationship enabled in the Edit Relationship dialog box and Go to Related Record is performed from an empty portal row, the script might produce unexpected results.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (41, 'en', 4, 'notes', 'Notes', '-
If the related records can''t be found, this script step returns an error code which can be captured with the Get(LastError) function.

-
When this script step opens a new window, the new window doesn''t activate the OnFirstWindowOpen script trigger or the OnWindowOpen script trigger, because the triggered script may not go to the desired layout or view. If you want a script performed after this script step opens a new window, add Perform Script as the next script step.

-
The sort order is not maintained if the related records are in an external file.

-
If this script step is performed in the context of a filtered portal''s row and the Show only related records option is set, only the filtered records are in the new found set. However, if the focus is not in the filtered portal''s row, the new found set can include all the related records, not just the filtered records.

-
The Animation option is supported only in FileMaker Go:

-
You can use animations only for the selected window.

-
You can''t use animations for navigating between records by using the slider or the status toolbar buttons.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (41, 'en', 5, 'ref-example1', 'Example 1', 'Goes to a related record in the Invoices table and sorts the found set of related records.

Copy

Go to Related Record [Show only related records; From table: "Invoices"; Using layout: "Invoices" (Invoices)]
Sort Records [Restore; With dialog: Off]
Go to Record/Request/Page [First]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (41, 'en', 6, 'ref-examplen', 'Example 2', 'Goes to a related record in the Invoices table and sorts the found set of related records in a new window.

Copy

Go to Related Record [Show only related records; From table: "Invoices"; Using layout: "Invoices" (Invoices); New Window]
Sort Records [Restore; With dialog: Off]
Go to Record/Request/Page [First]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (41, 'en', 7, 'ref-examplen', 'Example 3', 'Displays a related record in the Invoices table by sliding the record in from left.

Copy

Go to Related Record [Show only related records; From table: "Invoices"; Using layout: "Invoices" (Invoices); Animation: Slide in from Left]');
