INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (42, 'en', 1, 'ref-options', 'Options', '- Select entire contents deletes the entire contents of a field. If you do not use Select entire contents, only the selected portion of the field''s data is deleted.

- Go to target field specifies the field whose contents you want to delete.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (42, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (42, 'en', 3, 'ref-desc', 'Description', 'This script step removes the contents of the field in the current record without placing the contents on the Clipboard. If you want to cut and paste the field information, use the Cut script step. Use Undo immediately to restore the contents.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (42, 'en', 4, 'notes', 'Notes', '- If you manually select field data before you run this script step in FileMaker WebDirect, the script step performs as if you did not make a selection. To select field data before you run this script step in FileMaker WebDirect, use the Set Selection script step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (42, 'en', 5, 'ref-example1', 'Example 1', 'Clears the Email field in the current record.

Copy

Show Custom Dialog ["Do you want to clear the customer''s email address?"]
If [Get ( LastMessageChoice ) = 1]
    Clear [Select; Customers::Email]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (42, 'en', 6, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (43, 'en', 0, 'ref-see-also', 'See also', '-
