- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (45, 'en', 1, 'ref-options', 'Options', '- Select entire contents replaces the contents of a field with the contents of the Clipboard. If you do not use Select entire contents, Paste copies the contents of the Clipboard to the currently selected portion of the field.

- Paste without style tells FileMaker Pro to ignore all text style and formatting associated with the Clipboard contents.

- Go to target field specifies the field to paste into.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (45, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (45, 'en', 3, 'ref-desc', 'Description', 'If you try to paste data that doesn''t match the field type of the target field, FileMaker Pro pastes the data but displays a validation alert when you attempt to exit the field. If the field is not on the current layout, FileMaker Pro returns an error code which can be captured with the Get(LastError) function.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (45, 'en', 4, 'notes', 'Notes', '- If you manually select field data before you run this script step in FileMaker WebDirect, the script step performs as if you did not make a selection. To select field data before you run this script step in FileMaker WebDirect, use the Set Selection script step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (45, 'en', 5, 'ref-example1', 'Example 1', 'Pastes the Clipboard contents into the active field.

Copy

Show Custom Dialog ["Do you want to paste the Clipboard contents?"]
If [Get ( LastMessageChoice ) = 1]
    Paste [Select]
End If');
