INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (47, 'en', 4, 'ref-example1', 'Example 1', 'Selects the contents of the active field.

Copy

Show Custom Dialog ["Do you want to select the contents of the active field?"]
If [Get ( LastMessageChoice ) = 1]
    Select All
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (47, 'en', 5, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (48, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (48, 'en', 1, 'ref-options', 'Options', '- Go to target field specifies the field whose contents you want to select. If no target field is specified, the active field is used.

- Start Position specifies the starting position of the selection.

- End Position specifies the ending position of the selection.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (48, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (48, 'en', 3, 'ref-desc', 'Description', 'A position within a field is determined by the number of characters, including spaces, beginning with position 1, the first character in the field. A selection includes all values beginning with the start position and concluding with the end position. For example, if Field1 has the value "abcdefgh", and the script step options specify a start position of 3 and an end position of 6, the script step will select "cdef". If the start position is in range and the end position is out of range, then everything from the start position to the end of the field is selected. (A position is in range if it is between 1 and the length of the text in the field.)

To move the cursor without selecting text, you can specify position values that are out of range or have the end position before the start position:
To move the cursor
Set
Before position n
Start Position = n and End Position = 0
After position n
Start Position = 0 and End Position = n
To the start of the field
Start Position ≤ 1 and End Position = 0
To the end of the field
Start Position > m and End Position ≥ m, where m is the length of text in the field

Or set Start Position ≤ 0 and End Position < 0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (48, 'en', 4, 'notes', 'Notes', '- No action is taken if the user attempts to perform a selection on a container field.

- For all clients except FileMaker WebDirect, data selected out of visual range is scrolled into view.

- In FileMaker Go, this script step does not highlight selected text if the keyboard is hidden on the device.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (48, 'en', 5, 'ref-example1', 'Example 1', 'Selects the first 5 digits of the Postal Code field.

Copy

Set Selection [Customers::Postal Code; Start Position: 1; End Position: 5]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (48, 'en', 6, 'ref-examplen', 'Example 2', 'Selects the number of paragraphs that the user specifies in the custom dialog box.

Copy

Show Custom Dialog ["How many paragraphs do you want to select?"; Products::Number of Paragraphs]
If [Get ( LastMessageChoice ) = 1]
    Set Selection [Products::Description; Start Position: 1; End Position: Position ( Products::Description ; ¶ ; 1 ; Products::Number of Paragraphs )]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (48, 'en', 7, 'ref-examplen', 'Example 3', 'Moves the cursor before the third character in the field.

Copy

Set Selection [Table::Field1; Start Position: 3; End Position: 0]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (48, 'en', 8, 'ref-examplen', 'Example 4', 'Moves the cursor after the third character in the field.

Copy

Set Selection [Table::Field1; Start Position: 0; End Position: 3]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (48, 'en', 9, 'ref-examplen', 'Example 5', 'Moves the cursor to the start of the field.

Copy

Set Selection [Table::Field1; Start Position: 0; End Position: 0]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (48, 'en', 10, 'ref-examplen', 'Example 6', 'Moves the cursor to the end of the field.

Copy

Set Selection [Table::Field1; Start Position: -1; End Position: -1]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (48, 'en', 11, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (49, 'en', 0, 'ref-see-also', 'See also', '- Keyboard shortcuts (Windows)

- Keyboard shortcuts (macOS)

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (49, 'en', 1, 'ref-options', 'Options', '- Undo reverses the previously performed action in the file.

- Redo restores the previously undone action in the file.

- Toggle switches between the two most recently performed actions in the file.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (49, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (49, 'en', 3, 'ref-desc', 'Description', 'Multiple actions can be undone by repeatedly executing this script step with the Undo option. The number of actions that can be undone or redone is limited only by the amount of available memory.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (49, 'en', 4, 'ref-example1', 'Example 1', 'Undoes data entry if the Phone Number field has fewer than seven digits.

Copy

If [Length ( Customer::Phone Number ) < 7]
    Show Custom Dialog ["Phone Number must contain at least 7 digits. Undo number input?"]
    If [Get ( LastMessageChoice ) = 1]
        Undo/Redo [Undo]
    End If
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (49, 'en', 5, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (50, 'en', 0, 'ref-see-also', 'See also', '- Exporting data from FileMaker Pro

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (50, 'en', 1, 'ref-options', 'Options', '-
Specify target field specifies the field to be exported. If no field is specified, FileMaker Pro exports the contents of the current field in the active table.

-
Specify output file specifies the name and location of the file to which the field contents will be exported. See Creating file paths. If no file is specified, the user is asked to choose a filename and location when the script step is performed.

You can select:

-
Automatically open file to have the output file open with the default application

-
Create email with file as attachment to display a new email message in the user''s default email application, with the output file attached

-
Create folders specifies whether to create new folders that you specify in the output file path.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (50, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (50, 'en', 3, 'ref-desc', 'Description', 'If the contents of the exported field is text, then this script step creates a UTF-16 format text file. To convert the text to another format first, use the TextEncode function.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (50, 'en', 4, 'notes', 'Notes', '-
In FileMaker WebDirect:

-
The Specify output file and Create folders options are not supported. FileMaker WebDirect exports field contents to the web browser''s default download location.

-
This script step is not supported in mobile browsers.

-
In FileMaker Go:

-
Text is exported as a UTF-8 format text file.

-
The Create folders option is not supported.

-
In FileMaker Data API, the Create folders option is not supported.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (50, 'en', 5, 'ref-example1', 'Example 1', 'Opens a dialog box to set the export path with a new folder and a filename, then exports the image.

Copy

Export Field Contents [Products::Picture; "Mobile Phone.png"; Create folders: On]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (50, 'en', 6, 'ref-examplen', 'Example 2', 'Exports files from the Container field in all the records in the found set to a set file path.

Copy

Go to Record/Request/Page [ First ]
Loop [ Flush: Always ]
    Set Variable [ $PATH ; Value: Get ( DocumentsPath ) & GetContainerAttribute ( Products::Container ; "filename" ) ]
    Export Field Contents [ Products::Container ; "$PATH" ; Create folders: Off ]
    Go to Record/Request/Page [ Next ; Exit after last: On ]
End Loop');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (50, 'en', 7, 'related', 'Related topics', '-
Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (51, 'en', 0, 'ref-see-also', 'See also', '- Working with audio and video in interactive containers

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (51, 'en', 1, 'ref-options', 'Options', '- Store only as reference instructs FileMaker Pro to store only a link to an audio or video file in the container field instead of the actual file. This option may reduce the size of your FileMaker Pro file, but if you move or delete the file being referenced, FileMaker Pro won''t be able to display it.

- Specify source file specifies the audio or video file you intend to insert in the interactive container. The file path must begin with movie, moviemac, moviewin, or movielinux. See Creating file paths.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (51, 'en', 2, 'ref-orig', 'Originated in version', '12.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (51, 'en', 3, 'ref-desc', 'Description', 'You must specify a field, click in a field, or use the Go to Field script step before performing this script step.

When Insert Audio/Video is performed, unless a file is specified with the Specify source file option, FileMaker Pro displays a dialog box where the user can select and preview the file to be imported.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (51, 'en', 4, 'notes', 'Notes', '- FileMaker WebDirect does not support the Store only as reference or Specify source file options.

- If there is no active container field on the layout where the script is being performed, Insert Audio/Video returns an error code that can be captured with the Get(LastError) function.

- This script step works only for interactive containers. For more information, see Specifying formats for container fields.

- For a list of supported media types, see Using data in container fields.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (51, 'en', 5, 'ref-example1', 'Example 1', 'Goes to the Media field and inserts an audio file using the relative path movie:Audio/Music.mp3.

Copy

Go to Field [Customers::Media]
Insert Audio/Video ["Music.mp3"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (51, 'en', 6, 'ref-examplen', 'Example 2', 'Inserts the media file specified in the Media Name field into the active container field by reference.

Copy

Set Variable [$MEDIA_PATH; Value: Get ( DocumentsPath ) & Products::Media Name]
Insert Audio/Video [Reference; "$MEDIA_PATH"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (51, 'en', 7, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (52, 'en', 0, 'ref-see-also', 'See also', '- Copying and moving data in records

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (52, 'en', 1, 'ref-options', 'Options', '- Select entire contents replaces the contents of a field or variable. If you don''t select this option:

- For a field, replaces only the selected portion of the active field, or inserts data at the insertion point. The default insertion point is at the end of the field''s data.

- For a variable that doesn''t have container data, inserts data at the end of the variable''s current value. For a variable that has container data, replaces the contents of the variable.

- Target specifies the field to paste the calculated result into or the variable to set. If the variable doesn''t exist, this script step creates it (see Using variables).

- Calculated result is the calculation whose result will be inserted by this script step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (52, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (52, 'en', 3, 'ref-desc', 'Description', 'You must specify a target variable, specify a target field on the current layout, click in a field, or use the Go to Field script step before performing this script step. If Target is not specified, the data is placed in the active field. Otherwise, this script step returns an error code that can be captured with the Get(LastError) function.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (52, 'en', 4, 'notes', 'Notes', '- If you manually select field data before you run this script step in FileMaker WebDirect, the script step performs as if you did not make a selection. To select field data before you run this script step in FileMaker WebDirect, use the Set Selection script step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (52, 'en', 5, 'ref-example1', 'Example 1', 'Inserts the current date if the invoice prints successfully.

Copy

Set Error Capture [On]
Print [With dialog: On]
Insert Calculated Result [Select; Invoices::Print Status; If ( Get ( LastError ) = 0 ; "Printed on " & Get ( CurrentDate ) ; "Not Printed" )]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (52, 'en', 6, 'related', 'Related topics', '- Set Field script step

- Defining calculation fields

- Script steps reference');
