INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (53, 'en', 4, 'notes', 'Notes', '- If you manually select field data before you run this script step in FileMaker WebDirect, the script step performs as if you did not make a selection. To select field data before you run this script step in FileMaker WebDirect, use the Set Selection script step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (53, 'en', 5, 'ref-example1', 'Example 1', 'Goes to the Email History layout, inserts the current date in the Last Sent field, then goes to the original layout.

Copy

Go to Layout ["Email History"]
Insert Current Date [Select; Emails::Last Sent]
Go to Layout [original layout]');
