INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (77, 'en', 7, 'ref-examplen', 'Example 3', 'Sets the next serial value after importing records. This is useful when Perform auto-enter options during import is not selected to preserve dates and other auto-entries.

Copy

Go to Layout [ "Products" (Products) ; Animation: None ]
Import Records [ With dialog: Off ; Table: Products ; Source: "New Product Catalog.xlsx" ; Worksheet: "Stock" ; Add ; Mac Roman ]
Set Next Serial Value [ Products::Product ID ; Get ( TotalRecordCount ) + 1 ]
Sort Records [ Restore ; With dialog: Off ]
Go to Record/Request/Page [ First ]');
