INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (185, 'en', 3, 'ref-desc', 'Description', 'This script step is the same as choosing Scripts menu > Script Workspace, or File menu > Manage > Scripts.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (185, 'en', 4, 'notes', 'Notes', '- Once an Open Script Workspace script step is performed, FileMaker Pro halts execution of the current script. This prevents unexpected conditions from occurring if the currently running script is edited.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (185, 'en', 5, 'ref-example1', 'Example 1', 'Displays a custom dialog box that asks if the user wants to manage the database''s scripts, and opens the Script Workspace.

Copy

Show Custom Dialog ["Do you want to manage database scripts?"]
If [Get ( LastMessageChoice ) = 1]
    Open Script Workspace
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (185, 'en', 6, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (186, 'en', 0, 'ref-see-also', 'See also', '- Sharing files on a network

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (186, 'en', 1, 'ref-options', 'Options', 'None.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (186, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (186, 'en', 3, 'ref-desc', 'Description', 'This script step is the same as choosing File menu > Sharing > Share with FileMaker Clients.

Use this script step to open the FileMaker Network Settings dialog box for users if you have restricted their access to FileMaker Pro menus.

If an app is hosted by FileMaker Cloud and this script step is performed in FileMaker WebDirect, the Share dialog box opens.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (186, 'en', 4, 'notes', 'Notes', '-
To change account access settings in this dialog, your account must have full access privileges or the Manage extended privileges privilege (see Editing other privileges). To enable users without the necessary privileges to perform this script step, you can right-click the current script in the scripts pane and choose Grant Full Access Privileges, if you have full access privileges. See Creating and editing scripts.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (186, 'en', 5, 'ref-example1', 'Example 1', 'Displays a custom dialog box that asks if the user wants to share the current database, and opens the FileMaker Network Settings dialog box.

Copy

Show Custom Dialog ["Do you want to share this database?"]
If [Get ( LastMessageChoice ) = 1]
    Open Sharing
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (186, 'en', 6, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (187, 'en', 0, 'ref-see-also', 'See also', '- Uploading files to a host

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (187, 'en', 1, 'ref-options', 'Options', 'None.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (187, 'en', 2, 'ref-orig', 'Originated in version', '13.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (187, 'en', 3, 'ref-desc', 'Description', 'This script step is the same as choosing File menu > Sharing > Upload to Host.

Use this script step to open the Upload to Host dialog box for users if you have restricted their access to FileMaker Pro menus.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (187, 'en', 4, 'ref-example1', 'Example 1', 'Displays a custom dialog box that asks if the user wants to upload a database to a host, and opens the Upload to Host dialog box.

Copy

Show Custom Dialog ["Do you want to upload a database to a host?"]
If [Get ( LastMessageChoice ) = 1]
    Open Upload to Host
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (187, 'en', 5, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (188, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (188, 'en', 1, 'ref-options', 'Options', 'Enter comments.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (188, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (188, 'en', 3, 'ref-desc', 'Description', 'Use comments to document your script. Comments appear in bold and are prefaced with a #. Comments are present only when you are viewing the script and do not appear when the script is performed.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (188, 'en', 4, 'notes', 'Notes', '- To add a new line in the comment text, press:

- Windows: Ctrl+Enter or Alt+Enter

- macOS: Ctrl-Return or Opt-Return

- Comments print in italics.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (188, 'en', 5, 'ref-example1', 'Example 1', 'Shows how comments are used to explain script steps.

Copy

Go to Layout ["Invoices"]
#Find all invoices for the current customer
Find Matching Records [Replace; Invoices::Customer ID]
#Sort found set by Invoice ID
Sort Records [Restore; With dialog: Off]
#Save all records in the found set as a PDF
Save Records as PDF [With dialog: Off; "Customer Backup.pdf"; Records being browsed ; Create folders: Off]
#Go back to the original layout
Go to Layout [original layout]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (188, 'en', 6, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (189, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (189, 'en', 1, 'ref-options', 'Options', '- On indicates that the formatting bar, the View menu > Formatting Bar menu item, and the Formatting Bar button in the layout bar are enabled.

- Off hides the formatting bar, disables the View menu > Formatting Bar menu item, and disables the Formatting Bar button in the layout bar.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (189, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (189, 'en', 3, 'ref-desc', 'Description', 'This script step works in all modes except Layout mode.

Use this script step to disable the formatting bar and menu items related to the formatting bar. This script step only affects the active window of the file from which the script step is called.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (189, 'en', 4, 'ref-example1', 'Example 1', 'Goes to the Comments field on the Invoice Details layout and enables the Formatting Bar button and menu item.

Copy

Go to Layout [ "Invoice Details" ]
Go to Field [ Invoices::Comments ]
Allow Formatting Bar [ On ]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (189, 'en', 5, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (190, 'en', 0, 'ref-see-also', 'See also', '- About container fields

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (190, 'en', 1, 'ref-options', 'Options', '- Source specifies the source for the media:

- Layout Object specifies the layout object to play the media from.

- Field specifies the container field to play the media from. The field doesn''t need to be present on the layout.

- URL specifies the URL to play the media from. You can type the URL or create a URL from a calculation.

If no source is specified, the script step will use the active layout object, when possible.

- Presentation specifies how to display the media. If the source for the media is a field or a URL, the only options for Presentation are Full Screen Only and Audio Only.

- Start Full Screen starts playing the media in full screen but allows changing the presentation to embedded.

- Full Screen Only plays the media in full screen.

- Start Embedded starts playing the media as embedded but allows changing the presentation to full screen.

- Embedded Only plays the media as embedded. It doesn''t allow users to change the presentation to full screen.

- Audio Only plays only the audio.

- Disable Interaction enables or disables user interaction with the playback. If this option is set to Yes, you cannot use the playback controls or gestures to interact with the media.

- Yes disables user interaction with the playback.

- No enables user interaction with the playback.

- Hide Controls shows or hides the playback controls while the media plays. If you hide the playback controls but enable interaction, you can use gestures instead of playback controls.

- Yes hides the playback controls.

- No shows the playback controls.

- Position specifies how many seconds from the beginning of the media to start playback.

- Start Offset specifies the beginning of the playback range in seconds from the beginning of the media. The media can be played only within the playback range. For example, if you set this option to 30, the user cannot rewind into or play the first 30 seconds of the media. The default value for this option is 0, which allows the media to start from the beginning.

- End Offset specifies the end of the playback range in seconds from the beginning of the media. The media can be played only within the playback range. For example, if you set this option to 100, the user cannot fast forward or play past the first 100 seconds of the media. The default value for this option is 0, which allows the media to play to the end.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (190, 'en', 2, 'ref-orig', 'Originated in version', '14.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (190, 'en', 3, 'ref-desc', 'Description', 'Use this script to play media files from container fields, layout objects, or URLs in FileMaker Go. The media can be an audio, a video, or an image file.

If the foreground window contains a media file that is playing when the window moves to the back, the media file continues to play.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (190, 'en', 4, 'ref-example1', 'Example 1', 'Plays a media file in full screen and hides playback controls after the OnRecordLoad script trigger is activated:

Copy

AVPlayer Play [Field: Library::Video; Presentation: Full Screen Only; Hide Controls: Yes]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (190, 'en', 5, 'ref-examplen', 'Example 2', 'Resumes playing a media file from the position at which it was last stopped.

Copy

Set Field [Library::Last Stopped Position; GetAVPlayerAttribute ("position")]
AVPlayer Play [Field: Library::Video; Position: Library::Last Stopped Position]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (190, 'en', 6, 'ref-examplen', 'Example 3', 'Plays the media file in full screen for iPhone, and embedded for iPad.

Copy

If [Get(Device) = 3 //iPad]
    AVPlayer Play [Object Name: "Container"; Presentation: Start Embedded]
Else If [Get(Device) = 4 //iPhone]
    AVPlayer Play [Object Name: "Container"; Presentation: Start Full Screen]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (190, 'en', 7, 'related', 'Related topics', '- Script steps reference

- AVPlayer Set Options script step

- AVPlayer Set Playback State script step

- GetAVPlayerAttribute function');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (191, 'en', 0, 'ref-see-also', 'See also', '- About container fields

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (191, 'en', 1, 'ref-options', 'Options', '- Presentation changes the setting for displaying the media.

- Start Full Screen starts playing the media in full screen but allows changing the presentation to embedded.

- Full Screen Only plays the media in full screen.

- Start Embedded starts playing the media as embedded but allows changing the presentation to full screen.

- Embedded Only plays the media as embedded and doesn''t allow changing the presentation to full screen.

- Audio Only plays only the audio.

- Disable Interaction changes the setting for enabling or disabling user interaction with the playback. If this option is set to Yes, you cannot use the playback controls or gestures to interact with the media.

- Yes disables user interaction with the playback.

- No enables user interaction with the playback.

- Hide Controls changes the setting for showing or hiding the playback controls while the media plays. If you hide the playback controls but enable interaction, you can use gestures instead of playback controls.

- Yes hides the playback controls.

- No shows the playback controls.

- Disable External Controls enables or disables the iOS or iPadOS playback controls on the lock screen or Control Center when the media is playing or is paused.

- Yes disables the playback controls.

- No enables the playback controls.

- Pause in Background changes the setting for playing the audio and video when FileMaker Go moves to the background. If this option is not set and FileMaker Go moves to the background, the audio continues to play, but the video is paused.

- Yes pauses the audio and video.

- No continues playing the audio and video.

- Position specifies how many seconds from the beginning of the media to move the current playback.

- Start Offset specifies the beginning of the playback range in seconds from the beginning of the media. The media can be played only within the playback range. For example, if you set this option to 30, the user cannot rewind into or play the first 30 seconds of the media. The default value for this option is 0, which allows the media to start from the beginning.

- End Offset specifies the end of the playback range in seconds from the beginning of the media. The media can be played only within the playback range. For example, if you set this option to 100, the user cannot fast forward or play past 100 seconds of the media. The default value for this option is 0, which allows the media to play to the end.

- Zoom specifies how to display the video:

- Fit preserves the aspect ratio and scales the video to fit within the playback area.

- Fill preserves the aspect ratio and scales the video to fill the playback area.

- Stretch stretches the video to fill the playback area, but it doesn''t preserve the aspect ratio.

- Fit Only doesn''t allow users to change the zoom setting to Fill or Stretch.

- Fill Only doesn''t allow users to change the zoom setting to Fit or Stretch.

- Stretch Only doesn''t allow users to change the zoom setting to Fit or Fill.

- Volume specifies a value between 0.0 and 1.0 as the volume level for the audio.

- Sequence specifies which media file should play next.

- None plays no additional media.

- Next plays the next media.

- Previous plays the previous media.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (191, 'en', 2, 'ref-orig', 'Originated in version', '14.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (191, 'en', 3, 'ref-desc', 'Description', 'Use this script step to change the settings for audio, video, or image files when the file is playing or is paused.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (191, 'en', 4, 'ref-example1', 'Example 1', 'Changes the setting of a video that is currently playing to start the playback 50 seconds from the beginning of the file. The video is stretched to fill the playback area without preserving the aspect ratio.

Copy

AVPlayer Set Options [Position: 50; Zoom: Stretch]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (191, 'en', 5, 'ref-examplen', 'Example 2', 'Enables user interaction with the playback after the video has played for 30 seconds.

Copy

AVPlayer Play [Object Name: "Container"; Disable Interaction: Yes]
Pause/Resume Script [Duration (seconds): 30]
AVPlayer Set Options [Disable Interaction: No]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (191, 'en', 6, 'ref-examplen', 'Example 3', 'Pauses the audio file that is playing if FileMaker Go moves to the background.

Copy

AVPlayer Set Options [Pause in Background: Yes]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (191, 'en', 7, 'related', 'Related topics', '- Script steps reference

- AVPlayer Play script step

- AVPlayer Set Playback State script step

- GetAVPlayerAttribute function');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (192, 'en', 0, 'ref-see-also', 'See also', '- About container fields

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (192, 'en', 1, 'ref-options', 'Options', '- Paused pauses playing the media file.

- Playing resumes playing a media file that has been paused.

- Stopped stops playing the media file. After a player is set to stop, it cannot be set to play with this script step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (192, 'en', 2, 'ref-orig', 'Originated in version', '14.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (192, 'en', 3, 'ref-desc', 'Description', 'Use this script step to pause, resume, or stop playing a media file that is playing or is paused.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (192, 'en', 4, 'ref-example1', 'Example 1', 'Resumes playing a media file that has been paused.

Copy

AVPlayer Set Playback State [Playing]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (192, 'en', 5, 'ref-examplen', 'Example 2', 'Stops a media file if it is playing.

Copy

If [GetAVPlayerAttribute("playbackState") = 1
    AVPlayer Set Playback State [Stopped]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (192, 'en', 6, 'related', 'Related topics', '- Script steps reference

- AVPlayer Play script step

- AVPlayer Set Options script step

- GetAVPlayerAttribute function');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (193, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (193, 'en', 1, 'ref-options', 'Options', 'None.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (193, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (193, 'en', 3, 'ref-example1', 'Example 1', 'Performs a find. If no records were found, beeps.

Copy

Set Error Capture [On]
Perform Find [Restore]
If [Get ( FoundCount ) = 0]
    Beep
    Show Custom Dialog ["No records were found."]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (193, 'en', 4, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (194, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (194, 'en', 1, 'ref-options', 'Options', '- With dialog specifies whether to display the Dial Phone dialog box when the script step is performed.

- Phone Number lets you enter a phone number to dial.

- Specify lets you create a calculation to generate the phone number.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (194, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (194, 'en', 3, 'ref-desc', 'Description', 'You can enter a phone number or specify a calculation to create a phone number. You can specify number, text, calculation, or global fields. Letters within the phone number are translated to numbers (except for q and z). You can also choose whether to use the current phone settings based on your current location.

Tip To place an international call in FileMaker Go, filter the phone number for numerical digits and the "+" symbol.

Important The Dial Phone script step is not supported in macOS, but you can create scripts that include the Dial Phone script step to use in FileMaker Go.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (194, 'en', 4, 'ref-example1', 'Example 1', 'Dials the phone number contained in the script.

Copy

Dial Phone [With dialog: On; "5550987654"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (194, 'en', 5, 'ref-examplen', 'Example 2', 'Dials the phone number contained in the Work Phone field in the current record.

Copy

Go to Layout ["Customer Details"]
If [not IsEmpty ( Customers::Work Phone )]
    Dial Phone [With dialog: Off; Customers::Work Phone]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (194, 'en', 6, 'ref-examplen', 'Example 3', 'Filters the contents of the Work Phone field for appropriate characters and dials the filtered number.

Copy

Go to Layout ["Customer Details"]
If [not IsEmpty ( Customers::Work Phone )]
    Dial Phone [With dialog: Off; Filter ( Customers::Work Phone ; "1234567890+" )]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (194, 'en', 7, 'related', 'Related topics', '- Filter function

- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (195, 'en', 0, 'ref-see-also', 'See also', '- Changing a touch keyboard type

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (195, 'en', 1, 'ref-options', 'Options', '- On enables the touch keyboard.

- Off disables the touch keyboard.

- Toggle switches between enabling and disabling the touch keyboard.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (195, 'en', 2, 'ref-orig', 'Originated in version', '14.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (195, 'en', 3, 'ref-desc', 'Description', 'Use this script to enable or disable the touch keyboard in FileMaker Go or Windows. Enable Touch Keyboard is used only for fields; it has no impact on the touch keyboard for dialog boxes.

You can use the Get(TouchKeyboardState) function to check the current setting of the touch keyboard.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (195, 'en', 4, 'ref-example1', 'Example 1', 'In FileMaker Go, enables the touch keyboard.

Copy

Enable Touch Keyboard [On]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (195, 'en', 5, 'ref-examplen', 'Example 2', 'Checks the current setting of the touch keyboard and disables the touch keyboard if it is enabled.

Copy

If [ Get ( TouchKeyboardState ) = 1]
    Enable Touch Keyboard [Off]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (195, 'en', 6, 'related', 'Related topics', '- Get(TouchKeyboardState) function

- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (196, 'en', 0, 'ref-see-also', 'See also', '-
Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (196, 'en', 1, 'ref-options', 'Options', '-
Select entire contents replaces the contents of a field or variable. If you don''t select this option:

-
For a field, replaces only the selected portion of the active field, or inserts data at the insertion point. The default insertion point is at the end of the field''s data.

-
For a variable that doesn''t have container data, inserts data at the end of the variable''s current value. For a variable that has container data, replaces the contents of the variable.

-
Target specifies the field to insert the result into or the variable to set. If the variable doesn''t exist, this script step creates it (see Using variables).

-
Request is a calculation that specifies the request as text. The text is a JSON object in the format described below.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (196, 'en', 2, 'ref-orig', 'Originated in version', '19.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (196, 'en', 3, 'ref-desc', 'Description', 'The FileMaker Data API is a REST API available as a web service for FileMaker Server and FileMaker Cloud. Web applications can use this API to send requests and receive data in JSON format from hosted FileMaker Pro files.

Using the same underlying functionality as the FileMaker Data API on FileMaker hosts, this script step enables a script performed by any FileMaker product to request data in the current file, whether hosted or not, and receive the data in JSON format. This script step doesn''t make a web service call to a host using the FileMaker Data API, nor does it depend on whether the API is enabled on a host. The similarity between this script step and the FileMaker Data API is only that the JSON format of the returned data is the same. The request is a simple JSON object, rather than the combination of URL, header, and request body required by the FileMaker Data API to use a FileMaker host''s web service. The result returned in Target is in the same JSON format as when requested from a host via the FileMaker Data API.

Request format

This script step supports the following key-value pairs in the JSON object specified by the Request option. If one of these keys isn''t specified in the request, the default value is used.
 Key   |  Default value   |  Description
action
"read"
read, metaData, create, update, delete, and duplicate are the supported values. Use metaData to retrieve information about tables and layouts. Use the other values to act on record data.
version
"v1"
v1, v2, and vLatest are supported values. Behavior and generated results differ based on the API version.
layouts

A layout name.
tables

A table occurrence name. Required for table occurrence metaData actions. Works like the layouts key. If the table occurrence is specified, the metadata for that table is returned. If no name is specified, the list of table occurrences is returned.
query
all records
An array of JSON objects, each specifying a field and find criteria.
recordId

The unique ID number of a record. You can''t specify both a query and recordId key.
sort

A JSON object that specifies sort order of records in the current layout''s table.
offset
1
The record number of the first record in a range of records in the current layout''s table.
limit
100
The maximum number of records that should be returned from the current layout''s table.
layout.response
value from layouts
To retrieve the data in the context of a different layout, specify a layout name.
portal
all portals
A JSON object that specifies a portal.
offset.portal-name
1
The record number of the first portal record in a range of related records. For portal-name, you must specify the portal''s object name, if it exists, otherwise the related table name.
limit.portal-name
50
The maximum number of related records that should be returned. For portal-name, you must specify the portal''s object name, if it exists, otherwise the related table name.
fieldData

A JSON object that specifies record data to create or update.
portalData

A JSON object that specifies related record data to create or update.
modId

(Optional) For an update action, the modification ID of the record to update. If it doesn''t match the current modId of the record, the record won''t be modified.
"options":
{"entrymode":"value"}
"user"
(Optional) When writing data, this script step ignores whether a field''s Allow user to override during data entry option is selected and uses the entrymode value instead. For value, use:

-
script: ignore a field''s data validation requirements

-
user: follow a field''s data validation requirements

See Defining field validation.
"options":
{"prohibitmode":"value"}
"user"
(Optional) When writing data, this script step ignores whether a field''s Prohibit modification of value during data entry option is selected and uses the prohibitmode value instead. For value, use:

-
script: ignore a field''s automatic data entry requirements

-
user: follow a field''s automatic data entry requirements

See Defining automatic data entry.

For more information about the keys listed above, see the topics under "Work with records" as well as "Get metadata" and "Perform a find request" in FileMaker Data API Guide.

The following keys are ignored:

-
databases is ignored because the database is always the one belonging to the window that the script is running in.

-
Authorization is ignored because the script''s privileges are either those of the current user or full access, if the current script has been granted full access privileges.

-
Content-Type is ignored because the request must be in JSON format.

-
script and any keys that start with script. are ignored. To perform another script, use the Perform Script script step instead.

Error handling

The JSON result in Target contains at least a messages key with an object containing message and code keys. The code values are those defined in FileMaker error codes. Most of the message and code values are the same as those returned by the FileMaker Data API available as a web service on FileMaker hosts. Some additional errors are unique to this script step and help to identify problems when parsing the Request option. These additional errors use code values of 3, 1708, and 1710 but use many different message values to provide more detail about the error.

The Get(LastError) and Get(LastErrorDetail) functions return the same values as in the code and message keys, respectively. Get(LastErrorLocation) returns where the error occurred in the script.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (196, 'en', 4, 'notes', 'Notes', '-
This script step executes in its own session unrelated to the context of any window or of a script that may be running, including the script that performs this script step. Therefore, use this script step as if you''re making a FileMaker Data API call to a host over the network. As such, script triggers and any error reporting dialog boxes are disabled while this script step is performed.

-
If the file is hosted by FileMaker Server or FileMaker Cloud, the returned values of container fields are URLs that can be used to fetch the field contents. If the file is opened locally, only the name of the file in the container field is returned.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (196, 'en', 5, 'ref-example1', 'Example 1', 'Returns metadata for all table occurrences by specifying no value for the tables key. In this case, there''s one source (or base) table (Products) and two table occurrences (Products and Products_InStock). This example uses the JSONSetElement function to create the JSON object in the Request option.

Copy

Execute FileMaker Data API [ Select ; Target: $$result ;
JSONSetElement ( "{}" ;
    [ "action" ; "metaData" ; JSONString ] ;
    [ "tables" ; "" ; JSONString ]
) ]
Set Variable [ $$result ; JSONFormatElements ( $$result ) ]

The JSON data returned in the global variable $$result has this form.

Copy

{
    "messages" :
    [
        {
            "code" : "0",
            "message" : "OK"
        }
    ],
    "response" :
    {
        "tables" :
        [
            {
                "baseTable" : "Products",
                "name" : "Products"
            },
            {
                "baseTable" : "Products",
                "name" : "Products_InStock"
            }
        ]
    }
}');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (196, 'en', 6, 'ref-examplen', 'Example 2', 'Based on the Products layout, returns the first record in the table associated with the Products layout.

Copy

Execute FileMaker Data API [ Select ; Target: $$result ;
JSONSetElement ( "{}" ;
    [ "layouts" ; "Products" ; JSONString ] ;
    [ "limit" ; 1 ; JSONNumber ]
) ]
Set Variable [ $$result ; JSONFormatElements ( $$result ) ]

The JSON data returned in the global variable $$result has this form.

Copy

{
    "messages" :
    [
        {
            "code" : "0",
            "message" : "OK"
        }
    ],
    "response" :
    {
        "data" :
        [
            {
                "fieldData" :
                {
                    "ID" : "FB1",
                    "Name" : "Donuts",
                    "Stock" : 43
                },
                "modId" : "6",
                "portalData" : {},
                "recordId" : "1"
            }
        ],
        "dataInfo" :
        {
            "database" : "Favorite Bakery",
            "foundCount" : 3,
            "layout" : "Products",
            "returnedCount" : 1,
            "table" : "Products",
            "totalRecordCount" : 3
        }
    }
}');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (196, 'en', 7, 'ref-examplen', 'Example 3', 'Based on the Products layout, performs a find for records where the Stock field is less than 40, and returns the found set sorted by the Stock field in descending order.

Copy

Execute FileMaker Data API [ Select ; Target: $$result ;
JSONSetElement ( "{}" ;
    [ "layouts" ; "Products" ; JSONString ] ;
    [ "query" ; "[ { \"Stock\":\"<40\" } ]" ; JSONArray ] ;
    [ "sort" ; "[ { \"fieldName\":\"Stock\" ,
                    \"sortOrder\":\"descend\" } ]" ; JSONArray ]
) ]
Set Variable [ $$result ; JSONFormatElements ( $$result ) ]

The JSON data returned in the global variable $$result has this form.

Copy

{
    "messages" :
    [
        {
            "code" : "0",
            "message" : "OK"
        }
    ],
    "response" :
    {
        "data" :
        [
            {
                "fieldData" :
                {
                    "ID" : "FB3",
                    "Name" : "Baguette",
                    "Stock" : 34
                },
                "modId" : "1",
                "portalData" : {},
                "recordId" : "7"
            },
            {
                "fieldData" :
                {
                    "ID" : "FB2",
                    "Name" : "Chocolate Cake",
                    "Stock" : 23
                },
                "modId" : "1",
                "portalData" : {},
                "recordId" : "6"
            }
        ],
        "dataInfo" :
        {
            "database" : "Favorite Bakery",
            "foundCount" : 2,
            "layout" : "Products",
            "returnedCount" : 2,
            "table" : "Products",
            "totalRecordCount" : 3
        }
    }
}');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (196, 'en', 8, 'ref-examplen', 'Example 4', 'Based on the Products layout, returns the first record in the table associated with the Products layout and if there are portal rows, return the first 2 records after the skipping the first 2.

Copy

Execute FileMaker Data API [ Select ; Target: $$result ;
JSONSetElement ( "{}" ;
    [ "layouts" ; "Products" ; JSONString ] ;
    [ "limit" ; 1 ; JSONNumber ] ;
    [ "[''limit.RelatedProducts'']" ; 2; JSONNumber ] ;
    [ "[''offset.RelatedProducts'']" ; 2 ; JSONNumber ]
) ]
Set Variable [ $$result ; JSONFormatElements ( $$result ) ]

The JSON data returned in the global variable $$result has this form.

Copy

{
    "messages" :
    [
        {
            "code" : "0",
            "message" : "OK"
        }
    ],
    "response" :
    {
        "data" :
        [
            {
                "fieldData" :
                {
                    "ID" : "FB1",
                    "Name" : "Donuts",
                    "Stock" : 43
                },
                "modId" : "6",
                "portalData" : {
                    "RelatedProducts" :
                    [
                        {
                            "ID" : "FB4",
                            "Name" : "Donut Holes",
                            "Stock" : 53
                        },
                        {
                            "ID" : "FB5",
                            "Name" : "Short Cake",
                            "Stock" : 15
                        }
                    ]
                },
                "recordId" : "1"
            }
        ],
        "dataInfo" :
        {
            "database" : "Favorite Bakery",
            "foundCount" : 3,
            "layout" : "Products",
            "returnedCount" : 1,
            "table" : "Products",
            "totalRecordCount" : 6
        }
    }
}');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (196, 'en', 9, 'ref-examplen', 'Example 5', 'Based on the Products layout, modifies the record specified by recordId, updating the values of the Stock and Name fields.

Copy

Execute FileMaker Data API [ Select ; Target: $$result ;
JSONSetElement ( "{}" ;
    [ "action" ; "update" ; JSONString ] ;
    [ "layouts" ; "Products" ; JSONString ] ;
    [ "recordId" ; "4" ; JSONString ] ;
    [ "fieldData" ; "{ \"Stock\" : 14 ,
       \"Name\" : \"Vanilla Cake, Large\" }" ; JSONObject ]
) ]
Set Variable [ $$result ; JSONFormatElements ( $$result ) ]

The JSON data returned in the global variable $$result has this form.

Copy

{
    "messages" :
    [
        {
            "code" : "0",
            "message" : "OK"
        }
    ],
    "response" :
    {
        "modId" : "6"
    }
}

If the record specified by recordId didn''t exist, Get(LastError) would return 101 and Get(LastErrorDetail) would return "Record is missing", which would be the same as code and message in $$result.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (196, 'en', 10, 'ref-examplen', 'Example 6', 'Based on the Products layout, creates a record and sets the values of the Stock, ID, and Name fields. Because the ID field is set to auto-enter a serial number and the Prohibit modification of value during data entry option is enabled, setting the prohibitmode key to script in the options object overrides that auto-enter requirement and sets the ID field as specified.

Copy

Execute FileMaker Data API [ Select ; Target: $$result ;
        JSONSetElement ( "{}" ;
        [ "action" ; "create" ; JSONString ] ;
        [ "layouts" ; "Products" ; JSONString ] ;
        [ "options" ; "{ \"prohibitmode\" : \"script\" }" ; JSONObject ] ;
        [ "fieldData" ; "{ \"Stock\" : 14 ,
           \"ID\" : \"FB42\" ,
           \"Name\" : \"Croissants\" }" ; JSONObject ]
        ) ]
        Set Variable [ $$result ; JSONFormatElements ( $$result ) ]

The JSON data returned in the global variable $$result has this form.

Copy

{
        "messages" :
        [
           {
               "code" : "0",
               "message" : "OK"
           }
        ],
        "response" :
        {
           "modId" : "0",
           "recordId" : "7"
        }
        }

If the ID field also had validation set to require a unique value and a record with the ID value of "FB42" already existed, then Get(LastError) would return 504 and Get(LastErrorDetail) would return "Value in field is not unique, as required in validation entry options", which would be the same as code and message in $$result.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (196, 'en', 11, 'related', 'Related topics', '-
FileMaker Data API Guide

-
Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (197, 'en', 0, 'ref-see-also', 'See also', '- Executing SQL to interact with data sources via ODBC

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (197, 'en', 1, 'ref-options', 'Options', '- With dialog specifies whether to display the Specify SQL dialog box, the Select ODBC Data Source dialog box, and the dialog box for entering a password when the script step is performed.

- ODBC Data Source displays the Select ODBC Data Source dialog box. Select a data source from the list, click OK, and enter a valid user name and password.
Note Select Save user name and password if you set With dialog to Off, or users may be unable to access your data source.

- Calculated SQL text specifies a calculation to use as the SQL query.

- SQL text lets you manually enter an SQL query statement.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (197, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (197, 'en', 3, 'ref-desc', 'Description', 'You can use this script step to manage data in an ODBC data source through an ODBC SQL interface. This provides more control over the FileMaker Pro interaction with ODBC data sources. You can add multiple Execute SQL steps to a script.

Important See Get functions for information about error handling.

- Get(LastErrorDetail) function returns the latest error state returned by ODBC.

- Get(LastError) function returns the last FileMaker Pro error.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (197, 'en', 4, 'notes', 'Notes', '- SQL statements are limited to a maximum length of 256 K characters (512 KB).

- Server-side scripts, FileMaker WebDirect, the FileMaker Data API, and Custom Web Publishing support this script only if the With dialog option is set to Off.

- If you use the Execute SQL script step to send ODBC data that contains Unicode strings, your ODBC driver must support Unicode. Otherwise, the results may be inconsistent.

- Because Microsoft SQL Server supports both Unicode and non-Unicode field types, you must prefix all Unicode strings with an uppercase "N" (which stands for "National" in the SQL-92 standard). Otherwise, when a Unicode string containing non-English characters is passed to Microsoft SQL Server, you may lose any data that doesn''t exist in the Microsoft SQL Server code page.

- The Execute SQL script step performs SQL statements against ODBC data sources, not FileMaker data sources. To query tables in a FileMaker data source using only SQL SELECT statements, use the ExecuteSQL function.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (197, 'en', 5, 'ref-example1', 'Example 1', 'Updates records in the Employees table of an external ODBC data source.

Copy

Execute SQL [With dialog: On; SQL Text: INSERT INTO Employees (EmployeeID, FirstName, LastName, Title, WorkPhone, Salary) VALUES (100, N''Joe'', N''Smith'', N''Software Engineer'', ''987-7000'', 100000) UPDATE Employees SET Title = N''Manager'' WHERE EmployeeID = 103 DELETE FROM Employees WHERE EmployeeID = 103]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (197, 'en', 6, 'ref-examplen', 'Example 2', 'Calculates and performs an SQL statement to update records in the Customers table of an external ODBC data source.

Copy

Execute SQL [With dialog: On; Calculated SQL Text: "INSERT INTO Customers (Company, LastName) VALUES (" & Customers::Company & "," & "N''" & Customers::Last & "'')"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (197, 'en', 7, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (198, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (198, 'en', 1, 'ref-options', 'Options', 'None.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (198, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (198, 'en', 3, 'ref-desc', 'Description', 'The Exit Application script step does the following in other FileMaker clients:

- In FileMaker WebDirect, logs out the current web session and returns you to the FileMaker WebDirect Launch Center.

- In FileMaker Go, closes all open databases and leaves FileMaker Go running.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (198, 'en', 4, 'ref-example1', 'Example 1', 'Prevents the user from opening the database on a weekend. Started by the OnFirstWindowOpen script trigger.

Copy

Allow User Abort [Off]
If [DayName ( Get ( CurrentDate ) ) = "Saturday" or DayName ( Get ( CurrentDate ) ) = "Sunday"]
    Exit Application
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (198, 'en', 5, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (199, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (199, 'en', 1, 'ref-options', 'Options', 'None.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (199, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (199, 'en', 3, 'ref-desc', 'Description', 'FileMaker clients automatically flush (save) changes from their internal file cache to the computer''s hard disk (or other storage) during idle time. Use this script step to force FileMaker clients to flush their internal file cache after extensive changes have been made through script steps such as Import Records or Replace Field Contents.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (199, 'en', 4, 'ref-example1', 'Example 1', 'Assigns serial numbers to all records in the found set and flushes the changes to the disk.

Copy

Perform Find [Restore]
Sort Records [Restore; With dialog: On]
Go to Record/Request/Page [First]
Replace Field Contents [With dialog: Off; Products::Serial Number; Serial numbers]
Flush Cache to Disk');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (199, 'en', 5, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (200, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (200, 'en', 1, 'ref-options', 'Options', 'None.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (200, 'en', 2, 'ref-orig', 'Originated in version', '26.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (200, 'en', 3, 'ref-desc', 'Description', 'This script step immediately clears all cookies and session data stored by web viewers in all open FileMaker Pro files, not just the current file or a specific web viewer object. In FileMaker clients, web viewers share cookies at the application level. This means that if a user signs in to a web service (like email or cloud storage) in a web viewer in one file, that authenticated session persists across all files and all FileMaker user accounts on the same device.

Use this script step primarily for security and privacy scenarios where users need to clear authenticated sessions, such as in shared device environments or when switching between different user accounts.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (200, 'en', 4, 'notes', 'Notes', '-
Cookies are permanently removed with no undo capability. Users may need to re-authenticate to web services after execution.

-
This script step may be particularly useful when the FileMaker client can''t be restarted (for example, in Single App Mode on iOS and iPadOS).');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (200, 'en', 5, 'ref-example1', 'Example 1', 'Clears all web viewer cookies before prompting the next FileMaker user to sign in, preventing them from accessing the previous user''s authenticated web sessions.

Copy

Flush Web Viewer Cookies
Re-Login [ With dialog: On ; Current File ]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (200, 'en', 6, 'ref-examplen', 'Example 2', 'When a user needs to switch accounts in a web-based service displayed in a web viewer with the object name WebViewer_OAuth, flushes cookies to force the web service to prompt for new credentials.

Copy

Flush Web Viewer Cookies
Refresh Object [ Object Name: "WebViewer_OAuth" ; Repetition: 1 ]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (200, 'en', 7, 'ref-examplen', 'Example 3', 'Provides users with a way to manually clear all web viewer session data for privacy or compliance requirements.

Copy

Show Custom Dialog [ "Clear Session Data?" ; "This will sign you out of all web services in web viewers." ]
If [ Get ( LastMessageChoice ) = 1 ]
    Flush Web Viewer Cookies
    Show Custom Dialog [ "Session Cleared" ; "All web viewer sessions have been cleared." ]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (200, 'en', 8, 'related', 'Related topics', '-
Set Web Viewer script step

-
Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (201, 'en', 0, 'ref-see-also', 'See also', '- Opening and managing files

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (201, 'en', 1, 'ref-options', 'Options', '- Allow Folder Creation lets users create new folders while they browse the file system.

- Variable sets a local or global variable to the path of the selected folder. See the Set Variable script step.

- Dialog title lets you specify a custom name for the folder selection dialog box.

- Default location lets you specify the path that the folder selection dialog box displays when it opens.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (201, 'en', 2, 'ref-orig', 'Originated in version', '14.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (201, 'en', 3, 'ref-desc', 'Description', 'This script step prompts the user to select a folder, then it sets a variable to the fully qualified path of the selected folder.

In Windows, the path format is /Drive:/<selected folder>/.

In macOS, the path format is /DriveName/<selected folder>/.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (201, 'en', 4, 'ref-example1', 'Example 1', 'Opens a folder selection dialog box that displays the desktop, prompts the user to select the Pictures folder, then sets Products::Pictures Folder to the path of the selected folder.

Copy

Get Folder Path [$FOLDER; "Select the Pictures folder"; Get(DesktopPath)]
Set Field [Products::Pictures Folder; $FOLDER]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (201, 'en', 5, 'ref-examplen', 'Example 2', 'Performs a find, prompts the user to select a folder to export to, then loops through records to export files that are in the Products::Picture field.

Copy

Perform Find [Restore]
Get Folder Path [Allow Folder Creation; $FOLDER; "Export to Folder"]
Loop [ Flush: Always ]
    Set Variable [$PATH; Value:$FOLDER & Products::Picture]
    Export Field Contents [Products::Picture; $PATH ; Create folders: Off]
    Go to Record/Request/Page [Next; Exit after last: On]
End Loop');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (201, 'en', 6, 'related', 'Related topics', '- Creating file paths

- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (202, 'en', 0, 'ref-see-also', 'See also', '- Creating and editing custom menu sets

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (202, 'en', 1, 'ref-options', 'Options', '- Specify the menu set to install.

- Use as file default overrides the file''s default menu set specified in the Manage Custom Menus dialog box with the menu set specified in this script step. Once you close the file, the default menu set reverts to the one specified in the Manage Custom Menus dialog box. Select the menu set that you want the script step to install from the list.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (202, 'en', 2, 'ref-orig', 'Originated in version', '8.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (202, 'en', 3, 'ref-example1', 'Example 1', 'Goes to the Invoice Details layout and installs the Invoices Menu Set if the Print Invoices Menu Set was installed.

Copy

Go to Layout ["Invoice Details"]
If [Get ( CustomMenuSetName ) = "Print Invoices Menu Set"]
    Install Menu Set ["Invoices Menu Set" ; Use as file default: Off]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (202, 'en', 4, 'related', 'Related topics', '- Get(CustomMenuSetName) function

- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (203, 'en', 0, 'ref-see-also', 'See also', '-
Installing plug-ins

-
Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (203, 'en', 1, 'ref-options', 'Options', 'Specify target field specifies the container field with the plug-in that you want to install or update. If no field is specified, FileMaker Pro installs the plug-in in the current container field in the active table.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (203, 'en', 2, 'ref-orig', 'Originated in version', '12.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (203, 'en', 3, 'ref-desc', 'Description', 'You must insert the plug-in in a container field before you can install or update the plug-in. See Insert File or Installing plug-ins.

Only FileMaker plug-in files can be installed. If a non-plug-in file is located in the target or active container field, no action takes place when the script runs. The plug-in extension must be .fmx64 (Windows), .fmplugin (macOS), or .fmx (Linux).

Compressed plug-in files in ZIP format or plug-in files in TAR format can''t be installed.

You can use the Get(InstalledFMPlugins) function to identify the name, version, and enabled state of an installed plug-in. This function can help you determine whether the installed plug-in is newer or older than the plug-in required by the solution file. See Get(InstalledFMPlugins) or Get(InstalledFMPluginsAsJSON).

Plug-ins must be enabled in the plug-in settings for FileMaker Pro to recognize them. If the Install Plug-In File script step installs a plug-in update but the plug-in is disabled in the plug-in settings, FileMaker Pro installs the update but does not enable the plug-in. See Changing plug-in settings.

For files hosted by FileMaker Server, the server administrator must enable the Install Plug-In File script step in Admin Console. See FileMaker Server Help.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (203, 'en', 4, 'notes', 'Notes', '-
The system administrator can use the personalization file during an installation on multiple computers to disable plug-ins and prevent plug-in updates from installing in FileMaker Pro. See FileMaker Pro Network Install Setup Guide.

-
This script step is not supported in server-side scripts performed by a FileMaker Cloud host.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (203, 'en', 5, 'ref-example1', 'Example 1', 'Installs the Video plug-in.

Copy

Show Custom Dialog ["Do you want to install the latest version of the Video Plug-In?"]
If [Get ( LastMessageChoice ) = 1]
    Install Plug-In File[Plugins::Video]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (203, 'en', 6, 'ref-examplen', 'Example 2', 'Installs a plug-in from the appropriate container field based on the operating system and hardware architecture of the system where this script is run.

Copy

Set Variable [ $plugin_json ; Value: Get ( InstalledFMPluginsAsJSON ) ]
Set Variable [ $arch ; Value: JSONGetElement ( $plugin_json ; "environment.architecture" ) ]
Set Variable [ $platform ; Value: GetAsNumber ( JSONGetElement ( $plugin_json ; "environment.platform" ) ) ]

# macOS
If [ $platform = 1 ]
    If [ $arch = "arm64" ]
        # Apple silicon
        Install Plug-In File [ Plugins::macOS_Universal ]
    Else If [ $arch = "x86_64" and IsEmpty ( Plugins::macOS_Universal ) ]
        # Intel and no Universal plug-in available
        Install Plug-In File [ Plugins::macOS_Intel ]
    Else
        # Intel and Universal plug-in available
        Install Plug-In File [ Plugins::macOS_Universal ]
    End If
    Exit Script [ Text Result: "Plug-in for macOS installed" ]
End If

# Windows
If [ $platform = -2 ]
    Install Plug-In File [ Plugins::Windows_64bit ]
    Exit Script [ Text Result: "Plug-in for Windows installed" ]
End If

# Linux
If [ $platform = 5 ]
    If [ PatternCount ( Get ( HostApplicationVersion ) ; "Cloud Server 2" ) > 0 ]
    Else
        Install Plug-In File [ Plugins::Linux ]
        Exit Script [ Text Result: "Plug-in for Linux installed" ]
    End If
End If

Show Custom Dialog [ "Plug-ins are not supported on this platform." ]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (203, 'en', 7, 'ref-examplen', 'Example 3', 'See Plug-in update example.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (203, 'en', 8, 'related', 'Related topics', '-
Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (204, 'en', 0, 'ref-see-also', 'See also', '- Using URLs in a field

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (204, 'en', 1, 'ref-options', 'Options', '-
With dialog specifies whether to display the "Open URL" Options dialog box when the script step is performed.

-
In external browser specifies whether to open the page in the external web browser (FileMaker Go only). When off, the page opens within FileMaker Go.

-
URL allows you to type the URL or to create your URL from a calculation.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (204, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (204, 'en', 3, 'ref-desc', 'Description', 'Open URL supports http, https, ldap, ldaps, ftp, file, mailto, fmp, and fmpXX URL types, using the application registered with the operating system for each URL type (or scheme). For example, if the URL starts with http, the FileMaker client opens the user''s web browser and processes the URL.

If the specified URL contains spaces or other special characters, replace the characters with the corresponding encoded values required for valid URLs. For example, replace "@" with "%40".

The format of the fmp and fmpXX URL types to open FileMaker Pro files is described in Opening FileMaker Pro files using a URL.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (204, 'en', 4, 'notes', 'Notes', '-
FileMaker WebDirect does not support the file scheme.

-
In macOS, to open a remote file using the file scheme, mount the remote volume first. Then start the path with file:///Volumes/ (not the host name or IP address) followed by the volume name: file:///Volumes/MyVolumeName.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (204, 'en', 5, 'ref-example1', 'Example 1', 'Opens the user''s web browser and displays the Claris International Inc. homepage.

Copy

Open URL [With dialog: Off; "https://www.claris.com/"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (204, 'en', 6, 'ref-examplen', 'Example 2', 'In Windows, opens Notepad and opens the file My_File.txt on the root level of the user''s hard disk.

Copy

Open URL [With dialog: Off; "file://c:/My_File.txt"]

In macOS, opens Preview and opens the file My_File.pdf in the Downloads folder of the user named username on the system hard disk.

Copy

Open URL [With dialog: Off; "file:///Volumes/Macintosh HD/Users/username/Downloads/My_File.pdf"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (204, 'en', 7, 'ref-examplen', 'Example 3', 'Launches the default email application, opens a new email, and uses the value in the Email field to address the message.

Copy

Open URL [With dialog: Off; "mailto:" & Customers::Email]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (204, 'en', 8, 'ref-examplen', 'Example 4', 'Opens a shared FileMaker Pro file running on another system.

Copy

Open URL [With dialog: Off; "fmp://account:password@host/database"]

Important Account name and password information entered in an Open URL script step is visible to users with script editing access privileges, and is therefore not secure.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (204, 'en', 9, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (205, 'en', 0, 'ref-see-also', 'See also', '- Scripting with Apple events (macOS)

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (205, 'en', 1, 'ref-options', 'Options', '- Calculated AppleScript specifies a calculation to use as the AppleScript text.

- Native AppleScript is the text of an AppleScript (up to 30000 characters). Indenting of repeat loops and conditional statements is not supported.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (205, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (205, 'en', 3, 'ref-desc', 'Description', 'You can create a calculation to generate the AppleScript commands to be sent, or you can type the commands directly into the Native AppleScript text area.

For calculated scripts and scripts stored in FileMaker Pro fields, the AppleScript commands are compiled each time the script is performed. If you type the script into the Native AppleScript text area, then FileMaker Pro compiles the script and detects any scripting or system errors. (The script is recompiled whenever it''s edited.)');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (205, 'en', 4, 'notes', 'Notes', '- Because AppleScript is a macOS feature, if you run a script containing a Perform AppleScript script step on a Windows computer, the script step is ignored. (An error code is generated, which can be captured with the Get(LastError) function.)

Tips on usage

- FileMaker Pro can use the Perform AppleScript script step to send Apple events to itself or to FileMaker Pro software running on other machines. For FileMaker Pro to receive Apple events, the user''s privilege set must have the fmextscriptaccess extended privilege enabled. See Editing extended privileges for a privilege set.

- Use Perform AppleScript to pass image data between FileMaker Pro and other applications. With AppleScript, you can pass images stored in container fields to other applications or pass images into FileMaker Pro container fields.

- Use Perform AppleScript to communicate with applets and other scriptable applications. For example, if you have created an AppleScript applet with sub-routines, you can call the handlers using the Perform AppleScript command, like this:

- Perform AppleScript ["tell application "My Applet" to doMyRoutine()"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (205, 'en', 5, 'ref-example1', 'Example 1', 'Opens the Documents folder of the current macOS user.

Copy

Perform AppleScript ["tell application "Finder" (*enter line break*) activate (*enter line break*) set x to path to documents folder (*enter line break*) open x (*enter line break*) end tell"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (205, 'en', 6, 'ref-examplen', 'Example 2', 'Sets the bounds of the Documents window to the specified size. The Documents folder must be open before this script runs.

Copy

Perform AppleScript ["tell application "Finder" to set bounds of window "Documents" to {170, 70, 1000, 600}"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (205, 'en', 7, 'ref-examplen', 'Example 3', 'Calculates and performs the AppleScript to install a network printer. "\" tells FileMaker Pro to recognize the symbol that follows as a character and not as a calculation operator.

Copy

Perform AppleScript ["do shell script \"lpadmin -p " & Printers::Name & " -E -v lpd://" & Printers::IP Address & " -P /Library/Printers/PPDs/Contents/Resources/" & Substitute ( Printers::Driver Name ; " " ; "\\\ " ) & ".gz -D \\\"" & Printers::Description & "\\\"\""]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (205, 'en', 8, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (206, 'en', 0, 'ref-see-also', 'See also', '- Scripting with JavaScript in web viewers

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (206, 'en', 1, 'ref-options', 'Options', '- Object Name is the name of the web viewer object. See Naming objects. If not specified, the active web viewer is used.

- Function Name is the name of the JavaScript function to perform. The name is case sensitive.

- Parameters are one or more optional text parameters to pass to the JavaScript function. Drag parameters to change the order.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (206, 'en', 2, 'ref-orig', 'Originated in version', '19.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (206, 'en', 3, 'ref-desc', 'Description', 'This script step performs a function in JavaScript code that is loaded by a webpage in a web viewer then waits for the JavaScript function to finish. Any value returned by the JavaScript function is ignored.

To run a FileMaker script from JavaScript, see Scripting with JavaScript in web viewers.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (206, 'en', 4, 'notes', 'Notes', '- While the JavaScript function is being performed, users can''t cancel the operation or perform any other actions.

- This script step doesn''t change which layout object has the focus. To change the focus to the web viewer, use the Go to Object script step.

- If the web viewer hasn''t finished loading the webpage when this script step is performed, the JavaScript function is not performed and Get(LastError) function returns an error. A web viewer might not have loaded the webpage because the web viewer has not been made visible yet, perhaps because it''s in a closed popover, not in the frontmost panel in a panel control, or not in the visible area of a layout.

- In FileMaker WebDirect:

- This script step works only if the web viewer''s webpage has the same origin as the FileMaker WebDirect webpage. See Scripting with JavaScript in web viewers.

- The user can''t click a web viewer to give it the focus. Therefore, you must specify the Object Name option or use the Go to Object script step first; otherwise, this script step will return an error.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (206, 'en', 5, 'ref-example1', 'Example 1', 'Performs the JavaScript function showForm without parameters in the web viewer named Calendar.

Copy

Perform JavaScript in Web Viewer [ Object Name: "Calendar" ; Function Name: "showForm" ]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (206, 'en', 6, 'ref-examplen', 'Example 2', 'Each segment of a button bar is set up to run the following script and pass in a different FileMaker script parameter value to specify a command for a JavaScript function to perform. The script calls the processCommand function in the web viewer named WebViewer and passes in the FileMaker script parameter and current date as parameters to the JavaScript function.

Copy

Perform JavaScript in Web Viewer [ Object Name: "WebViewer" ;
    Function Name: "processCommand" ;
    Parameters: Get ( ScriptParameter ), Get ( CurrentDate ) ]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (206, 'en', 7, 'related', 'Related topics', '- Script steps reference

- About formulas');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (207, 'en', 0, 'ref-see-also', 'See also', '-
Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (207, 'en', 1, 'ref-options', 'Options', '-
Object name is a named object on the current layout. See Naming objects.

-
Repetition (optional) lets you choose which field repetition to refresh. Defaults to 1. This option is ignored if the object is not a field.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (207, 'en', 2, 'ref-orig', 'Originated in version', '13.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (207, 'en', 3, 'ref-desc', 'Description', 'Refresh Object does not support repetition numbers when updating the visibility state of an object with a hidden condition.

If the specified object is in a portal, Refresh Object updates the object in every visible portal row.

If the repetition calculation returns zero, or the expression does not exist, all repetitions are refreshed.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (207, 'en', 4, 'notes', 'Notes', '-
To update all objects in the current window, use the Refresh Window script step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (207, 'en', 5, 'ref-example1', 'Example 1', 'Allows the user to log in to a different account and updates the visibility state of the Confidential object. The Confidential object hides when the user is not logged in to the Admin account.

Copy

Re-Login [With dialog: On]
Refresh Object ["Confidential"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (207, 'en', 6, 'related', 'Related topics', '-
Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (208, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (208, 'en', 1, 'ref-options', 'Options', '- Object Name is a named object on the current layout. If Object Name is not specified, Refresh Portal refreshes the active layout object. See Naming objects.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (208, 'en', 2, 'ref-orig', 'Originated in version', '14.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (208, 'en', 3, 'ref-desc', 'Description', 'Refresh Portal updates the join relationship and contents of a portal that displays related records. Use Refresh Portal when a global field used in the portal''s filter calculation has been modified. For example, Refresh Portal with the OnObjectExit script trigger will refresh a portal after users commit a change in a field used in the portal''s filter calculation.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (208, 'en', 4, 'notes', 'Notes', '- In FileMaker WebDirect, Refresh Portal performs the Refresh Window script step.

- If the layout object specified for Object Name is not a portal, Refresh Portal performs the Refresh Object script step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (208, 'en', 5, 'ref-example1', 'Example 1', 'Sets the value of a global field used in a portal''s filter calculation, then updates the portal.

Copy

Set Field [Customer::Filter; 16]
Refresh Portal [Object Name: "Customer Orders"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (208, 'en', 6, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (209, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (209, 'en', 1, 'ref-options', 'Options', '-
Window name specifies the window name of the open FileMaker Pro file to save. If not specified, the file for the current window is saved.

-
Replace UUIDs generates new UUIDs for all elements in the file before saving as an add-on package. This action can''t be undone.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (209, 'en', 2, 'ref-orig', 'Originated in version', '19.0');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (209, 'en', 3, 'ref-desc', 'Description', 'This script step creates an add-on package from an open FileMaker Pro file. The add-on is saved in this folder:

-
Windows: <drive>:\Users\<user>\AppData\Local\FileMaker\Extensions\AddonModules

-
macOS: /Users/<user>/Library/Application Support/FileMaker/Extensions/AddonModules

In this folder, the add-on is saved in two forms:

-
An uncompressed folder containing the files that make up the add-on. The current FileMaker Pro installation loads the add-on from this folder and makes it available immediately to install the add-on in your custom apps.

-
A compressed .fmaddon file that you can distribute to other users. Users with FileMaker Pro installed can double-click the .fmaddon file to add the uncompressed add-on folder to the above location on their computer.

For more on how to create an add-on, see the Knowledge Base.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (209, 'en', 4, 'notes', 'Notes', '-
If the script to create your add-on package is in the same file that you want to save as an add-on package, add the following to the beginning of your script''s name to prevent it from being included in your add-on:

__FMAddonTemplateDirectives_

Note that this prefix begins with two underscore characters (__) and ends with one underscore.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (209, 'en', 5, 'ref-example1', 'Example 1', 'Saves as an add-on package the file whose window name is My Add-on.

Copy

Save a Copy as Add-on Package [ Window name: "My Add-on" ; Replace UUIDs: Off ]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (209, 'en', 6, 'related', 'Related topics', '-
Script steps reference

-
Working with add-ons');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (210, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (210, 'en', 1, 'ref-options', 'Options', '- Service Name is the name of the application that executes the commands. Refer to the documentation of the application you specify for the valid service name. You can enter the service name directly as text or click Specify to create the service name from a calculation.

- Topic is a filename or text string that describes the topic that the application executes the commands on. Refer to the documentation of the application specified in the Service Name for valid topics. You can enter the topic name directly as text or click Specify to create the topic name from a calculation. For more information, see Creating file paths.

- Commands are a calculated value or text string that specifies what the application does. Refer to the documentation of the application specified in the Service Name for valid commands and formats. You can enter the commands directly as text or click Specify to create the commands from a calculation.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (210, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (210, 'en', 3, 'ref-desc', 'Description', 'This script step sends a DDE (Dynamic Data Exchange) command to another application to execute a series of commands available in that application.

- FileMaker Pro sends DDE execute commands but does not receive them.

- Because DDE is a Windows feature, if you run a script containing a Send DDE Execute script step on a macOS-based computer, the script step is ignored. (An error code is generated, which can be captured with the Get(LastError) function.)

- When a FileMaker Pro script first establishes a DDE connection, the connection stays open to perform subsequent script steps for the same service name and topic. If the script includes another DDE Execute script step using a different service name or topic, FileMaker Pro closes the current connection and opens another with the new service name and topic. All open connections close when the script is completed.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (210, 'en', 4, 'ref-example1', 'Example 1', 'Opens a URL in Internet Explorer. (Internet Explorer must be open when this step executes.)

Copy

Send DDE Execute [Service Name: "iexplore"; Topic: "WWW_OpenURL";
Commands: "example.com"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (210, 'en', 5, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (211, 'en', 0, 'ref-see-also', 'See also', '- Scripting with Apple events (macOS)

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (211, 'en', 1, 'ref-options', 'Options (Windows)', '- Send the <event name> message lets you choose between the following:

- open document/application tells FileMaker Pro to open a document file or application. Documents are opened using the application that Windows has associated with the document''s file type.

- print document tells FileMaker Pro to print a document in another application.

- File allows you to specify a document/application to open, or a document to print. For more information, see Creating file paths.

- Calculation allows you to create a message from a calculation.

- Text allows you to manually enter text for the message to be sent.

- Bring target application to foreground activates the target application and display it on the screen. Displaying the target application can slow down the performance of your script. If Bring target application to foreground is not selected, the event is performed in the background.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (211, 'en', 2, 'ref-options', 'Options (macOS)', '- Send the <value> event with lets you choose between the following:

- open application tells FileMaker Pro to open an application. Click Specify Application to select the application.

- open document tells FileMaker Pro to open a document in the target application. You can also specify a calculated value or script.

- do script tells FileMaker Pro to perform a script in the language of the target application. Click Specify Application to select an application, and use Document to select the document to use with the target application. Or, select Script text and enter script text or type in the name of the script (make sure it is one that will be recognized by the target program).

- other displays the Specify event dialog box, where you can manually enter the Apple event Event class and Event ID.

- Document allows you to select the document you want used with the target application. For more information, see Creating file paths.

- Calculation allows you to create a calculation that generates a value you want to send with the event.

- Bring Target Application to foreground activates the target application and displays it on the screen. Displaying the target application can slow down the performance of your script. If Bring Target Application to foreground is not selected, the event is performed in the background.

- Wait for event completion before continuing tells FileMaker Pro to wait until the event is finished before continuing. If you don''t want to wait until the event is completed, deselect this option.

- Copy event result to the clipboard copies the resulting events data to the Clipboard, from which it can later be retrieved. This option is disabled if Bring Target Application to foreground is selected.

- Specify Application allows you to select the target application.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (211, 'en', 3, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (211, 'en', 4, 'ref-desc', 'Description', 'Send Event starts another application, opens a document in another application, or prints a document in another application (Windows); sends an Apple event to another application (macOS).

- Each Send Event script step sends one event. You can include more than one Send Event in a script.

- When specifying a document or application by calculation or text, the file type or application name will appear as <unknown> in the script definition.

- Windows: For additional scripting capabilities, you can create a program in Basic or C and run that program with this script step.

- macOS: When FileMaker Pro sends an Apple event, it sends text (not compiled) data. You must know what information the target application expects to receive with an event.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (211, 'en', 5, 'ref-example1', 'Example 1', 'In macOS, opens the TextEdit application.

Copy

Send Event ["TextEdit", "aevt", "oapp"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (211, 'en', 6, 'ref-examplen', 'Example 2', 'In Windows, opens the Notepad application.

Copy

Send Event ["aevt"; "odoc"; "NOTEPAD.EXE"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (211, 'en', 7, 'ref-examplen', 'Example 3', 'In Windows, opens the image.bmp file with its default application.

Copy

Send Event ["aevt"; "odoc"; "image.bmp"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (211, 'en', 8, 'related', 'Related topics', '- Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (212, 'en', 0, 'ref-see-also', 'See also', '-
Sending email messages based on record data

-
Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (212, 'en', 1, 'ref-options', 'Options', '-
Send via specifies whether your message will be sent by an email client, an SMTP server, or using OAuth 2.0. See Entering or editing SMTP options and Entering or editing OAuth 2.0 email options.

-
One email using data from the current record sends one message to all specified recipients.

-
Multiple emails (one for each record in found set) sends one message for each record in the found set to all specified recipients.

If you choose SMTP Server or OAuth 2.0 and Multiple emails (one for each record in the found set) and FileMaker Pro encounters an error while emailing one of the records, the remaining records will not be sent.

-
To stores the address(es) of the recipient(s).

-
CC stores the address(es) of the carbon copy recipient(s).

-
BCC stores the address(es) of the blind carbon copy recipient(s).

-
For To, CC, and BCC:

-
Windows: Choose Specify Email Addresses to enter one or more email addresses. Separate each address with a semicolon or carriage return character.

-
Choose Specify Field Name to specify a field that contains one or more email addresses.

-
Choose Specify Calculation to specify a calculation that generates one or more email addresses.

-
Select Collect addresses across found set to use all values from this field or calculation result in the current found set to address a message to multiple recipients. This option is available if you choose One email using data from the current file and use the Specify Field Name or Specify Calculation option to specify a value for the To, CC, or BCC entries.

Note If you specify multiple email addresses for To, CC, or BCC, separate each recipient''s email address with a carriage return or semicolon. Some email clients do not accept other separators, such as a comma.

-
Subject indicates the title for the email.

-
Message indicates the text of the email. You can type the message as text, use a field value, create a message from a calculation, or insert text from a file.

-
Click Attach Files to specify files to send as attachments with the message. (See Creating file paths.) Instead of searching a list of potential files and choosing the first file it can locate, this step attaches all the files in the list that it can find at the specified paths.

-
With dialog specifies how FileMaker Pro will handle the composed email. If you set With dialog to On, the composed message is left open for review in the email application. (In some applications, the new message is left in the Drafts folder.) If With dialog is Off, the composed email is placed in the email application''s outbox and sent when the device is connected to a network.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (212, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (212, 'en', 3, 'ref-desc', 'Description', 'Send Mail sends an intranet or internet email through an email application, via SMTP (Simple Mail Transfer Protocol), or via OAuth 2.0.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (212, 'en', 4, 'notes', 'Notes', '-
Sending mail using an email application is not supported in server-side scripts, the FileMaker Data API, and Custom Web Publishing.

-
Server-side scripts support sending mail via SMTP or OAuth 2.0. However, if you attach a file, that file needs to be in a folder that server-side scripts are allowed to access. See Paths in server-side scripts.

-
FileMaker WebDirect doesn''t support the Attach Files option. Web users must manually attach saved or exported files to email messages.

-
Custom Web Publishing and the FileMaker Data API don''t support the Attach Files option.

-
FileMaker WebDirect doesn''t support the With dialog: Off option when sending mail via an email client.

-
FileMaker Go doesn''t support the With dialog: Off option. The email displays on the device, and you can send the message manually.

-
If this script step sends an email via an email client in FileMaker WebDirect, limit the To, CC, BCC, Subject, and Body options to 2000 characters total. If the email contains more than 2000 characters, the web browser may not allow FileMaker WebDirect to send the message.

-
To send mail through an email application:

-
You must have a supported email application installed and configured properly on your computer. See FileMaker platform technical specifications.

-
Windows: A [Mail] section in the Win.ini file is required.

-
You can create a PDF or a Microsoft Excel file from your data to send as an attachment. See Save Records as PDF and Save Records as Excel.

-
The Send Mail script step does not control the font''s appearance. Use the email client to make any changes to the font.

-
FileMaker Pro sends email as plain text. To edit the message''s contents and formatting, choose to send the message through an email client and set the With dialog option to On. You can then edit the message within the email client before it is sent.

-
FileMaker Pro verifies the SSL certificate of an SMTP server that is using an encrypted connection. If the certificate cannot be verified, users can choose to connect anyway or cancel to skip this script step. If the certificate cannot be verified and the Set Error Capture script step is set to On, this script step behaves as if the server were unavailable. If the certificate cannot be verified in server-side scripts, the FileMaker Data API, Custom Web Publishing, and FileMaker WebDirect, this script step behaves as if it had been canceled by the user.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (212, 'en', 5, 'ref-example1', 'Example 1', 'Goes to the Customers layout, performs a find, and sends a prewritten email to the address in the Email field in the current record without prompting the user.

Copy

Go to Layout ["Customers"]
Perform Find [Restore]
Send Mail [Send via E-mail Client; With dialog: Off; To: Customers::Email; Subject: Invoices::Summary; Message: "Dear Customer,¶¶Thank you for your business."]
#The Collect addresses across found set option is not selected.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (212, 'en', 6, 'ref-examplen', 'Example 2', 'Saves the current record as a PDF, then emails the PDF to the address in the Email field in the current record.

Copy

Go to Layout ["Print Invoices"]
Save Records as PDF [Restore; With dialog: Off; "Invoice.pdf"; Current record ; Create folders: Off]
Send Mail [Send via E-mail Client; With dialog: Off; To: Customers::Email; Subject: Invoices::Summary; Message: "Dear Customer,¶¶Thank you for your business. Your invoice is attached."; "Invoice.pdf"]
Go to Layout [original layout]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (212, 'en', 7, 'related', 'Related topics', '-
Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (213, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (213, 'en', 1, 'ref-options', 'Options', '-
Specify the session identifier as text or a calculation whose result is text.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (213, 'en', 2, 'ref-orig', 'Originated in version', '19.4.1');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (213, 'en', 3, 'ref-desc', 'Description', 'By default, the session identifier is the same value returned by the Get(UserName) function. You can use this script step to change the session identifier so that it provides additional information to administrators. For each FileMaker client connected to a given host, there is only one value for the session identifier. This value remains in effect until Set Session Identifier is performed again in any custom app on the same host opened by the same client in the same session, or until the session ends.

The session identifier is available to administrators in the following ways:

-
FileMaker Server Admin Console displays the session identifier on the Databases page.

-
The Access log for FileMaker Server includes an entry that shows when this script step changed the session identifier from one value to another.

-
The FileMaker Admin API returns the session identifier as the userName value using the List Clients call on FileMaker Server and FileMaker Cloud.

See FileMaker Server Help and FileMaker Admin API Guide.

Best practices

-
If each user signs in with a unique account, you can identify them by their account name. In that case, there may be no reason to use Set Session Identifier.

-
If multiple users sign in with the same account or use the Guest account, their account names don''t identify them. If you have an alternative method to identify these users, you can use Set Session Identifier to make those users'' identifiers available to administrators in the ways described above.

-
Perform Set Session Identifier in a start-up script (a script activated by the OnFirstWindowOpen script trigger) so that the session identifier is set when the session begins.

-
If you have more than one custom app on a host, use the same method to determine the session identifier in each app''s start-up script. Otherwise, the identifier may change when the same user opens different apps.

-
If your app includes a script that allows users to sign out and sign in again as a different user (for example, using the Re-Login script step), your script may also need to perform Set Session Identifier to update the session identifier.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (213, 'en', 4, 'notes', 'Notes', '-
This script step doesn''t change the value returned by the Get(UserName) function.

-
If the current app is a local file, this script step does nothing.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (213, 'en', 5, 'ref-example1', 'Example 1', 'For a student survey, prompts users to enter their student ID, uses a custom function (IsStudentIDValid) to check that the student ID is valid, then sets the session identifier to the student ID.

Copy

Set Field [ Survey::StudentID ; "" ]
Show Custom Dialog [ Message: "Enter your student ID number." ; Survey::StudentID ]
If [ IsStudentIDValid ( Survey::StudentID ) ]
    Set Session Identifier [ Survey::StudentID ]
Else
    Show Custom Dialog [ "A valid student ID is required." ]
    Exit Script [ Result: "A valid student ID was not provided." ]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (213, 'en', 6, 'related', 'Related topics', '-
Script steps reference

-
Get(SessionIdentifier) function');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (214, 'en', 0, 'ref-see-also', 'See also', '- Working with web viewers on layouts

- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (214, 'en', 1, 'ref-options', 'Options', '- Object Name is the name of the web viewer to act upon. See Naming objects.

- Action lets you choose one of the following:

- Reset resets the named web viewer to its originally specified web address. This action also clears this web viewer''s Back and Forward history.

- Reload reloads the webpage that the web viewer is displaying.

- Go Forward goes forward one page, the same way a web browser does.

- Go Back goes back one page, the same way a web browser does.

- Go to URL lets you specify a new web address to load in the web viewer. The new web address is a calculation that you specify in the "Set Web Viewer - Go to URL" Options dialog box. In this script step, you cannot change whether the web viewer allows interaction, shows a progress bar or status messages, displays content in Find mode, or automatically encodes a URL. You can set these options only when you add or change a web viewer in Layout mode.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (214, 'en', 2, 'ref-orig', 'Originated in version', '8.5');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (214, 'en', 3, 'ref-desc', 'Description', 'This script step works only for named web viewer objects.

To specify the object name, either type the name in the Object Name box or click Specify and create a calculation.

If you choose the action Go to URL:

- You specify a web address in much the same way you do when you create a web viewer on a layout. For more information, see Working with web viewers on layouts.

- You can send html data to a web viewer by including the data in a URL, using the following format:

data:[<mediatype>][;base64],<data>

Where the following syntax applies:

dataurl = "data:" [ mediatype ] [ ";base64" ] "," data

mediatype = [ type "/" subtype ] *( ";" parameter )

data = *urlchar

parameter = attribute "=" value

More information about the "data URL scheme" can be found on the web.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (214, 'en', 4, 'notes', 'Notes', '- FileMaker Pro supports only UTF-16 character encoding. Character data encoded using other methods will not display the target of the URL.

- FileMaker WebDirect does not support the GoForward and GoBack options.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (214, 'en', 5, 'ref-example1', 'Example 1', 'Resets the web viewer named Product Website to its originally specified web address.

Copy

Set Web Viewer [Object Name: "Product Website"; Action: Reset]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (214, 'en', 6, 'ref-examplen', 'Example 2', 'Displays the Claris International Inc. homepage in the Product Website web viewer:

Copy

Set Web Viewer [Object Name: "Product Website"; URL: "https://www.claris.com"]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (214, 'en', 7, 'ref-examplen', 'Example 3', 'Displays the URL entered in the Website field in the Product Website web viewer:

Copy

Set Web Viewer [Object Name: "Product Website"; URL: Products::Website]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (214, 'en', 8, 'ref-examplen', 'Example 4', 'Uses the data URL scheme to display a small icon in a web viewer named WV2.

Copy

Set Web Viewer [Object Name: "WV2"; URL: "data:image/gif;base64,R0lGODlhFwAMAKEAAL+/v///AAAAUwAAACH5BAEAAAAALAAAAAAXAAwAAAI7hBGHapHcXJKPumizpigI+QliSH0XIjokWJ6oB4+qt0Zmaqpjesxz7st1YD8ZEbhJajAuDgfSYTx60wIAOw=="]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (214, 'en', 9, 'related', 'Related topics', '- Script steps reference

- Working with web viewers on layouts

- Naming objects');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (215, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (215, 'en', 1, 'ref-options', 'Options', 'General options

-
Title specifies the title of the custom dialog box. You can enter literal text or click Specify to create the dialog box title from a calculation.

-
Message specifies the message of the dialog box. You can enter literal text or click Specify to create the message text from a calculation.

-
Button Labels specifies how many buttons (up to three) to display in the custom dialog box and labels for these buttons. If you leave a button label blank, the button does not appear in the custom dialog box. If you leave all button titles blank, an OK button displays in the lower-right corner of the custom dialog box. To create a button label based on a calculation, click Specify and then specify the calculation.

-
Commit Data checkboxes pass input from the dialog box to the target field or variable according to the action of each button. When a field is the target, if no fields on the layout are active, the data is committed; if a field is active, the data is committed when the record is committed. If the checkbox is not enabled for a button and users enter data in the input field, no data is committed to the record or stored in the variable when users click the button.

-
Height is the height of the dialog, in points.

-
Width is the width of the dialog, in points.

-
From Top is the dialog''s distance, in points, from the top of the screen.

-
From Left is the dialog''s distance, in points, from the left of the screen.

Input Field options

-
Show input field <n> activates an input field.

-
Specify selects the target field or variable for input.

-
Use password character (*) masks text as it is entered, or as it is displayed from the database. This option obscures data being input into the custom dialog box or being displayed, but does not alter the actual data as it is stored in the database.

-
Label specifies a label (the text that will identify this input to the user). You can enter literal text or create the label from a calculation.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (215, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (215, 'en', 3, 'ref-desc', 'Description', 'The "Show Custom Dialog" Options dialog box allows you to set the dialog box title, message text, buttons, size, and position, and specify up to three fields or variables to use for input or display. The script pauses as long as the custom dialog box stays on the screen. Fields used for input can be of type text, number, date, time, timestamp, or container. Variables used for input store values as text. Your custom dialog box can also have up to three buttons, with custom button titles.

Use the Get(LastMessageChoice) function to determine which button the user presses.

-
1 for the first button (by default, labeled OK)

-
2 for the second button (by default, labeled Cancel)

-
3 for the third button');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (215, 'en', 4, 'notes', 'Notes', '-
If values entered into input fields don''t match the target field type, a validation error message displays. The user must resolve validation errors before the dialog box can be closed. See Defining field validation.

-
The target fields you specify don''t need to appear on the current layout. Show Custom Dialog input fields are independent of layouts, similar to the Set Field script step.

-
Data can''t be inserted into calculation or summary fields.

-
Show Custom Dialog ignores any field entry options. See Allowing or preventing entry into fields.

-
Data entry via the Show Custom Dialog script step is limited by any access privileges criteria that may be in place. (To enable the script for all users, right-click the current script in the scripts pane and choose Grant Full Access Privileges.)

-
Before you change the data commitment status of a button for a database that''s already in use, consider the behavior that users currently expect of the button and how changing its behavior could affect the validity of data committed (or not committed) to the database.

-
The Height, Width, From Top, and From Left options specify the size and position of the dialog on the screen.

-
A default minimum size is used if the specified size is smaller.

-
If size or position is unspecified, default values are used for the unspecified size or position. If both size and position are unspecified and if the dialog was displayed before, the size and position when it was last closed are used.

-
FileMaker Go doesn''t support the size and position options.

-
In FileMaker WebDirect, the position is relative to the top left of the web browser window. If both size and position are unspecified, default values are used.

-
(Windows) You can create a keyboard shortcut for a custom dialog box button by placing an ampersand before the shortcut key letter in the button label. For example, to create a keyboard shortcut ‘D'' (Alt+D) for a button labeled ‘Done'', type the label ‘&Done''.

-
To develop more-complex custom dialog boxes, you can use the New Window script step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (215, 'en', 5, 'ref-example1', 'Example 1', 'Performs a find. If no records were found, displays a custom dialog box.

Copy

Perform Find [Restore]
If [Get (FoundCount) = 0]
    Show Custom Dialog ["No records were found."]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (215, 'en', 6, 'ref-examplen', 'Example 2', 'Displays a custom dialog at a specified size in the center of the current window.

Copy

Set Variable [ $height ; Value: 200 ]
Set Variable [ $width ; Value: 400 ]
Show Custom Dialog [ Message: "Message in the center of the current window" ; Height: $height ; Width: $width ; Top: Get ( WindowTop ) + ( Get ( WindowHeight ) - $height ) / 2 ; Left: Get ( WindowLeft ) + ( Get ( WindowWidth ) - $width ) / 2 ]');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (215, 'en', 7, 'ref-examplen', 'Example 3', 'Creates a new record, prompts the user to enter information, then goes to the Customer Details layout. The first button is Cancel so that users don''t inadvertently create a record by pressing Return or Enter in the custom dialog box.

Copy

Freeze Window
New Record/Request
Show Custom Dialog ["New Customer"; "Enter information into the fields below:"; Customers::Company; Customers::Name; Customers::City]
If [Get ( LastMessageChoice ) = 1]
    Delete Record/Request [With dialog: Off]
Else
    Go to Layout ["Customer Details"]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (215, 'en', 8, 'ref-examplen', 'Example 4', 'Enters Find mode, prompts the user for find criteria, and performs the find. If the find returns no records, asks if the user wants to find again, and either performs the script again or halts all scripts.

Script: Find

Copy

Enter Find Mode [Pause: Off]
Show Custom Dialog ["Find customers by ID, name, or city."; Customers::ID; Customers::Name; Customers::City]
If [Get ( LastMessageChoice ) = 1]
    Perform Find [ ]
    If [Get ( FoundCount ) = 0]
        Show Custom Dialog ["No records were found. Find again?"]
        If [Get ( LastMessageChoice ) = 1]
            #Calls this script as a sub-script
            Perform Script [Specified: From list ; "Find" ; Parameter: ]
        Else
            Show All Records
            #Halts all scripts and sub-scripts
            Halt Script
        End If
    End If
Else If [Get ( LastMessageChoice ) = 2]
    Enter Browse Mode [Pause: Off]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (215, 'en', 9, 'related', 'Related topics', '-
Script steps reference');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (216, 'en', 0, 'ref-see-also', 'See also', '- Automating tasks with scripts');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (216, 'en', 1, 'ref-options', 'Options', '- Type the text to be spoken directly in the text entry area, or click Specify to create your spoken text from a calculation.

- Use Voice specifies a voice from the various voices available on your computer.

- Wait for speech completion before continuing tells FileMaker Pro to wait until the speech is completed before continuing with the next script step.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (216, 'en', 2, 'ref-orig', 'Originated in version', '6.0 or earlier');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (216, 'en', 3, 'ref-desc', 'Description', 'You can enter a literal text string or use a calculation to create the text to be spoken. You can also specify which voice synthesizer to use and whether or not to wait for the speech to be completed, before continuing with the next script step.

If the database is opened on a non-speaking computer, the script can still be edited, but only the default voice synthesizer is available. Speak script steps are not executed when the script is run on a non-speaking computer.');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (216, 'en', 4, 'ref-example1', 'Example 1', 'Tells the user to enter a company name if the Company field is empty. Can be started by the OnRecordCommit script trigger, OnLayoutExit script trigger, OnWindowClose script trigger, or OnWindowTransaction script trigger.

Copy

If [IsEmpty ( Contacts::Company )]
    Speak ["Enter a company name"]
End If');
INSERT INTO "script_step_sections" ("script_step_id", "locale", "position", "section_key", "heading", "body_text") VALUES (216, 'en', 5, 'ref-examplen', 'Example 2', 'Speaks the contents of the Summary field in the current record.

Copy

Go to Layout ["Invoice Details"]
Speak [Invoices::Summary]');
